export const WorkoutMenu: React.FC<{ isOpen: boolean; setIsOpen: (open: boolean) => void }> = ({ isOpen, setIsOpen }) => {
  const { plans, startWorkout, savePlan, deletePlan, reorderPlans, recentlyImportedPlanId, commitStartWorkout } = useWorkout();
  const { settings } = useSettings();

  const [view, setView] = useState<'list' | 'editor' | 'log'>('list');
  const [editingPlan, setEditingPlan] = useState<WorkoutPlan | null>(null);
  const [selectedPlanIds, setSelectedPlanIds] = useState<string[]>([]);
  const [showInfoForPlan, setShowInfoForPlan] = useState<WorkoutPlan | null>(null);

  // Editor State
  const addStep = () => {
      if (!editingPlan) return;
      const newStep: WorkoutStep = {
          id: Date.now().toString(),
          name: 'New Exercise',
          type: 'exercise',
          isRepBased: false,
          duration: settings.defaultExerciseDuration,
          reps: 10,
      };
      setEditingPlan({ ...editingPlan, steps: [...editingPlan.steps, newStep] });
  };

  const updateStep = (index: number, updates: Partial<WorkoutStep>) => {
      if (!editingPlan) return;
      const newSteps = [...editingPlan.steps];
      newSteps[index] = { ...newSteps[index], ...updates };
      setEditingPlan({ ...editingPlan, steps: newSteps });
  };

  const removeStep = (index: number) => {
      if (!editingPlan) return;
      const newSteps = [...editingPlan.steps];
      newSteps.splice(index, 1);
      setEditingPlan({ ...editingPlan, steps: newSteps });
  };

  const moveStep = (from: number, to: number) => {
      if (!editingPlan || to < 0 || to >= editingPlan.steps.length) return;
      const newSteps = [...editingPlan.steps];
      const [moved] = newSteps.splice(from, 1);
      newSteps.splice(to, 0, moved);
      setEditingPlan({ ...editingPlan, steps: newSteps });
  };

  const handleSavePlan = () => {
      if (editingPlan) {
          savePlan(editingPlan);
          setView('list');
          setEditingPlan(null);
      }
  };

  const handleCreatePlan = () => {
      setEditingPlan({
          id: Date.now().toString(),
          name: 'New Plan',
          steps: [],
          executionMode: 'linear'
      });
      setView('editor');
  };

  const handleEditPlan = (plan: WorkoutPlan) => {
      setEditingPlan(JSON.parse(JSON.stringify(plan))); // Deep copy
      setView('editor');
  };

  const handleStartSelected = () => {
      if (selectedPlanIds.length > 0) {
          startWorkout(selectedPlanIds);
          commitStartWorkout();
          setIsOpen(false);
          setSelectedPlanIds([]);
      }
  };

  const togglePlanSelection = (id: string) => {
      setSelectedPlanIds(prev => prev.includes(id) ? prev.filter(pid => pid !== id) : [...prev, id]);
  };

  return (
    <>
      {isOpen && <div className="fixed inset-0 bg-black/60 z-40" onClick={() => setIsOpen(false)}></div>}

      <div className={`fixed top-0 left-0 h-full w-full max-w-sm bg-gray-800/95 backdrop-blur-md shadow-2xl z-50 transform transition-transform duration-300 ${isOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-4 h-full flex flex-col">
            <div className="flex justify-between items-center mb-6">
