                                <div key={plan.id} className={`bg-gray-700/50 p-3 rounded-lg border-2 ${selectedPlanIds.includes(plan.id) ? 'border-blue-500' : 'border-transparent'} ${recentlyImportedPlanId === plan.id ? 'animate-pulse bg-blue-900/20' : ''}`}>
