                                removeStep={removeStep} 
                                moveStep={moveStep} 
                                totalSteps={editingPlan.steps.length}
                            />
                        ))}
                        <button onClick={addStep} className="w-full py-3 border-2 border-dashed border-gray-600 text-gray-400 rounded-lg hover:border-gray-500 hover:text-white transition-colors">
                            + Add Exercise
