    return (
        <div className={`${stepBgClass} rounded-lg relative`} style={{ borderLeft: `3px solid ${color || 'transparent'}` }}>
            {!isExpanded && (
                <button
                    onClick={(e) => {
                        e.stopPropagation();
                        removeStep(index);
                    }}
                    className="absolute top-1 right-1 p-1 text-gray-400 hover:text-red-500 hover:bg-red-500/10 rounded-full z-10"
