                </button>
            </div>
            {isExpanded && (
                <div className="p-3 border-t border-gray-600/50 space-y-3">
                   <div className="flex items-center gap-2">
                       <input 
                           type="text"
                           value={step.name}
                           onChange={e => updateStep(index, { name: e.target.value })}
