const PlanEditor: React.FC<{ 
    plan: WorkoutPlan | null; 
    onSave: (plan: WorkoutPlan) => void; 
    onCancel: () => void;
}> = ({ plan, onSave, onCancel }) => {
    const { settings, updateSettings } = useSettings();
    const { user } = useAuth();

    // Initialize state with default values or existing plan
    const [name, setName] = useState(plan?.name || '');
    const [steps, setSteps] = useState<WorkoutStep[]>(plan?.steps || []);
    const [executionMode, setExecutionMode] = useState<'linear' | 'circuit'>(plan?.executionMode || 'linear');
    const [color, setColor] = useState(plan?.color || COLORS[0]);
    const [expandedStepIndex, setExpandedStepIndex] = useState<number | null>(null);

    // Save draft periodically if editing a new plan or a fresh start
    useEffect(() => {
        if (!plan && name && steps.length > 0) {
            const draft: WorkoutPlan = {
                id: 'draft',
                name,
                steps,
                executionMode,
                color,
            };
            saveEditorDraft(draft);
        }
    }, [name, steps, executionMode, color, plan]);

    // Recover draft on mount if not editing existing
    useEffect(() => {
        if (!plan) {
            const draft = getEditorDraft();
            if (draft) {
                if (window.confirm("You have an unsaved plan draft. Would you like to restore it?")) {
                    setName(draft.name);
                    setSteps(draft.steps);
                    setExecutionMode(draft.executionMode || 'linear');
                    setColor(draft.color || COLORS[0]);
                } else {
                    clearEditorDraft();
                }
            }
        }
    }, [plan]);

    const handleSave = () => {
        if (!name.trim()) {
            alert("Please enter a plan name.");
            return;
        }
        if (steps.length === 0) {
            alert("Please add at least one step.");
            return;
        }

        const newPlan: WorkoutPlan = {
            id: plan?.id || Date.now().toString(),
            name,
            steps,
            executionMode,
            color,
            order: plan?.order, // Preserve order if editing
            version: 2,
        };

        onSave(newPlan);
        clearEditorDraft();
    };

    const updateStep = (index: number, newStepData: Partial<WorkoutStep>) => {
        const newSteps = [...steps];
        newSteps[index] = { ...newSteps[index], ...newStepData };
        setSteps(newSteps);
    };

    const removeStep = (index: number) => {
        const newSteps = steps.filter((_, i) => i !== index);
        setSteps(newSteps);
    };

    const handleAddSets = (newSteps: WorkoutStep[]) => {
        setSteps([...steps, ...newSteps]);
    };

    return (
        <div className="flex flex-col h-full">
             <div className="mb-4">
                <input
                    type="text"
                    value={name}
                    onChange={e => setName(e.target.value)}
                    placeholder="Plan Name"
                    className="w-full bg-gray-700 text-xl font-bold p-3 rounded-lg focus:outline-none focus:ring-2 ring-blue-500 mb-4"
                />
                 <div className="flex gap-4 mb-4">
                    <div className="flex-1">
                        <label className="block text-sm text-gray-400 mb-1">Color</label>
                        <div className="flex gap-2">
                            {COLORS.map(c => (
                                <button
                                    key={c}
                                    onClick={() => setColor(c)}
                                    className={`w-6 h-6 rounded-full transition-transform ${color === c ? 'scale-125 ring-2 ring-white' : ''}`}
                                    style={{ backgroundColor: c }}
                                />
                            ))}
                        </div>
                    </div>
                     <div className="flex-1">
                        <label className="block text-sm text-gray-400 mb-1">Mode</label>
                        <div className="flex rounded-md bg-gray-700 border border-gray-600 overflow-hidden">
                           <button onClick={() => setExecutionMode('linear')} className={`flex-1 px-3 py-1 text-sm ${executionMode === 'linear' ? 'bg-blue-600 text-white' : 'text-gray-300'}`}>Linear</button>
                           <button onClick={() => setExecutionMode('circuit')} className={`flex-1 px-3 py-1 text-sm ${executionMode === 'circuit' ? 'bg-blue-600 text-white' : 'text-gray-300'}`}>Circuit</button>
                        </div>
                     </div>
                 </div>
             </div>

             <div className="flex-grow overflow-y-auto space-y-2 pr-1 pb-4">
                 {steps.map((step, index) => (
                     <EditableStepItem
                        key={step.id || index}
                        index={index}
                        step={step}
                        updateStep={updateStep}
                        removeStep={removeStep}
                        isExpanded={expandedStepIndex === index}
                        onToggleExpand={() => setExpandedStepIndex(expandedStepIndex === index ? null : index)}
                        color={color}
                        settings={settings}
                        updateSettings={updateSettings}
                     />
                 ))}

                 <SetBuilder onAddSets={handleAddSets} />
             </div>

             <div className="flex gap-4 mt-4 pt-4 border-t border-gray-700">
                 <button onClick={onCancel} className="flex-1 py-3 bg-gray-600 hover:bg-gray-500 rounded-lg font-bold transition-colors">Cancel</button>
                 <button onClick={handleSave} className="flex-1 py-3 bg-green-600 hover:bg-green-500 rounded-lg font-bold transition-colors">Save Plan</button>
             </div>
        </div>
    );
};

const AICreator: React.FC<{ 
    onPlanCreated: (plan: WorkoutPlan) => void;
    onCancel: () => void;
}> = ({ onPlanCreated, onCancel }) => {
    const { settings } = useSettings();
    const [messages, setMessages] = useState<{role: 'user' | 'model', parts: {text: string}[]}[]>([]);
    const [inputValue, setInputValue] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const messagesEndRef = useRef<HTMLDivElement>(null);

    const scrollToBottom = () => {
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    };

    useEffect(scrollToBottom, [messages]);

    const handleSendMessage = async () => {
        if (!inputValue.trim()) return;

        const userMsg = inputValue;
        setInputValue('');
        setMessages(prev => [...prev, { role: 'user', parts: [{ text: userMsg }] }]);
        setIsLoading(true);

        try {
             // Construct user profile context string
             let profileContext = '';
             if (settings.userProfile) {
                 const { birthDate, fitnessLevel, equipment } = settings.userProfile;
                 if (birthDate) profileContext += `Age: ${new Date().getFullYear() - new Date(birthDate).getFullYear()} years old.\n`;
                 if (fitnessLevel) profileContext += `Fitness Level: ${fitnessLevel}.\n`;
                 if (equipment) {
                     const availableEq = equipment.filter(e => e.available).map(e => e.name).join(', ');
                     if (availableEq) profileContext += `Available Equipment: ${availableEq}.\n`;
                 }
             }

             const responseText = await generateWorkoutPlan(messages, userMsg, profileContext);

             // Extract JSON plan if present
             const jsonMatch = responseText.match(/```json\s*([\s\S]*?)\s*```/);
             let generatedPlan: WorkoutPlan | null = null;

             if (jsonMatch) {
                 try {
                     const parsed = JSON.parse(jsonMatch[1]);
                     // Basic validation
                     if (parsed.name && Array.isArray(parsed.steps)) {
                         generatedPlan = parsed;
                     }
                 } catch (e) {
                     console.error("Failed to parse AI JSON response", e);
                 }
             }

             setMessages(prev => [...prev, { role: 'model', parts: [{ text: responseText }] }]);

             if (generatedPlan) {
                 // Convert AI steps to our internal format if needed
                 const planToImport: WorkoutPlan = {
                     id: `ai_generated_${Date.now()}`,
                     name: generatedPlan.name,
                     steps: generatedPlan.steps.map((s: any, i: number) => ({
                         id: `step_${i}`,
                         name: s.name,
                         type: s.type || 'exercise',
                         isRepBased: !!s.isRepBased,
                         duration: s.duration || 45,
                         reps: s.reps || 10,
                         tip: s.tip
                     })),
                     executionMode: generatedPlan.executionMode || 'linear',
                     isSmartPlan: true,
                 };
                 // Instead of immediate import, we could show a button "Import Plan". 
                 // But for this simple implementation, let's just create it directly if confirmed or leave it in chat.
                 // Let's add a special UI message for plan ready.
             }

        } catch (error) {
             setMessages(prev => [...prev, { role: 'model', parts: [{ text: "Sorry, I encountered an error. Please try again." }] }]);
        } finally {
            setIsLoading(false);
        }
    };

    const handleImportFromChat = (text: string) => {
         const jsonMatch = text.match(/```json\s*([\s\S]*?)\s*```/);
         if (jsonMatch) {
             try {
                 const parsed = JSON.parse(jsonMatch[1]);
                 if (parsed.name && Array.isArray(parsed.steps)) {
                     const planToImport: WorkoutPlan = {
                         id: `ai_generated_${Date.now()}`,
                         name: parsed.name,
                         steps: parsed.steps.map((s: any, i: number) => ({
                             id: `step_${i}`,
                             name: s.name,
                             type: s.type || 'exercise',
                             isRepBased: !!s.isRepBased,
                             duration: s.duration || 45,
                             reps: s.reps || 10,
                             tip: s.tip
                         })),
                         executionMode: parsed.executionMode || 'linear',
                         isSmartPlan: true,
                         color: '#a855f7'
                     };
                     onPlanCreated(planToImport);
                 }
             } catch (e) {
                 alert("Could not parse plan from this message.");
             }
         }
    };

    return (
        <div className="flex flex-col h-full bg-gray-800 rounded-lg">
             <div className="p-4 border-b border-gray-700 flex justify-between items-center">
                 <h3 className="text-xl font-bold text-white flex items-center gap-2">
                     ✨ AI Coach
                 </h3>
                 <button onClick={onCancel} className="text-gray-400 hover:text-white">
                     <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                 </button>
             </div>

             <div className="flex-grow overflow-y-auto p-4 space-y-4">
                 {messages.length === 0 && (
                     <div className="text-center text-gray-400 mt-10">
                         <p className="text-lg">Tell me about your workout goals.</p>
                         <p className="text-sm mt-2">Example: "Create a 20-minute HIIT workout for beginners"</p>
                     </div>
                 )}
                 {messages.map((msg, i) => (
                     <div key={i} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                         <div className={`max-w-[85%] rounded-lg p-3 ${msg.role === 'user' ? 'bg-blue-600 text-white' : 'bg-gray-700 text-gray-200'}`}>
                             <div className="whitespace-pre-wrap">{msg.parts[0].text}</div>
                             {msg.role === 'model' && msg.parts[0].text.includes("```json") && (
                                 <button 
                                    onClick={() => handleImportFromChat(msg.parts[0].text)}
                                    className="mt-3 w-full py-2 bg-purple-600 hover:bg-purple-500 rounded text-white font-bold text-sm transition-colors"
                                 >
                                     Import This Plan
                                 </button>
                             )}
                         </div>
                     </div>
                 ))}
                 {isLoading && (
                      <div className="flex justify-start">
                          <div className="bg-gray-700 rounded-lg p-3 text-gray-400">
                              Thinking...
                          </div>
                      </div>
                 )}
                 <div ref={messagesEndRef} />
             </div>

             <div className="p-4 border-t border-gray-700 flex gap-2">
                 <input 
                     type="text" 
                     value={inputValue}
                     onChange={e => setInputValue(e.target.value)}
                     onKeyDown={e => e.key === 'Enter' && !isLoading && handleSendMessage()}
                     placeholder="Type your request..."
                     className="flex-grow bg-gray-900 text-white p-3 rounded-lg focus:outline-none focus:ring-2 ring-blue-500"
                     disabled={isLoading}
                 />
                 <button 
                    onClick={handleSendMessage}
                    disabled={isLoading || !inputValue.trim()}
                    className="p-3 bg-blue-600 rounded-lg text-white hover:bg-blue-500 disabled:opacity-50 disabled:cursor-not-allowed"
                 >
                     <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor">
                         <path d="M10.894 2.553a1 1 0 00-1.788 0l-7 14a1 1 0 001.169 1.409l5-1.429A1 1 0 009 15.571V11a1 1 0 112 0v4.571a1 1 0 00.725.962l5 1.428a1 1 0 001.17-1.408l-7-14z" />
                     </svg>
                 </button>
             </div>
        </div>
    );
};

export const WorkoutMenu: React.FC<{ isOpen: boolean; setIsOpen: (isOpen: boolean) => void }> = ({ isOpen, setIsOpen }) => {
  const { plans, deletePlan, savePlan, importPlan, reorderPlans, recentlyImportedPlanId, startWorkout } = useWorkout();
  const { user, signIn, signOut } = useAuth();

  const [view, setView] = useState<'list' | 'edit' | 'ai' | 'logs'>('list');
  const [editingPlan, setEditingPlan] = useState<WorkoutPlan | null>(null);

  const [inspectExerciseName, setInspectExerciseName] = useState<string | null>(null);
  const [infoPlan, setInfoPlan] = useState<WorkoutPlan | null>(null);
  const [sharePlan, setSharePlan] = useState<WorkoutPlan | null>(null);
  const [selectedPlanIds, setSelectedPlanIds] = useState<string[]>([]);

  // Drag and drop state
  const [draggedPlanIndex, setDraggedPlanIndex] = useState<number | null>(null);
  const [dragOverPlanIndex, setDragOverPlanIndex] = useState<number | null>(null);

  const handleEditPlan = (plan: WorkoutPlan | null) => {
    setEditingPlan(plan);
    setView('edit');
  };

  const handleSavePlan = (plan: WorkoutPlan) => {
      savePlan(plan);
      setEditingPlan(null);
      setView('list');
  };

  const handleAIPlanCreated = (plan: WorkoutPlan) => {
      importPlan(plan, 'ai');
      setView('list');
  };

  const handleDragStart = (e: React.DragEvent, index: number) => {
    setDraggedPlanIndex(index);
    e.dataTransfer.effectAllowed = "move";
    // Required for Firefox
    e.dataTransfer.setData("text/plain", index.toString());
  };

  const handleDragOver = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = "move";
    if (dragOverPlanIndex !== index) {
        setDragOverPlanIndex(index);
    }
  };

  const handleDrop = (e: React.DragEvent, index: number) => {
    e.preventDefault();
    if (draggedPlanIndex === null) return;

    if (draggedPlanIndex !== index) {
        const newPlans = [...plans];
        const [draggedItem] = newPlans.splice(draggedPlanIndex, 1);
        newPlans.splice(index, 0, draggedItem);
        reorderPlans(newPlans);
    }

    setDraggedPlanIndex(null);
    setDragOverPlanIndex(null);
  };

  const handleDragEnd = () => {
    setDraggedPlanIndex(null);
    setDragOverPlanIndex(null);
  };

  const handleDragLeave = () => {
     // Optional: logic to clear drag over style if leaving list area
  };

  const handleToggleSelection = (planId: string) => {
      setSelectedPlanIds(prev => {
          if (prev.includes(planId)) return prev.filter(id => id !== planId);
          return [...prev, planId];
      });
  };

  const handleMultiStart = () => {
      if (selectedPlanIds.length > 0) {
          startWorkout(selectedPlanIds);
          setIsOpen(false);
          setSelectedPlanIds([]);
      }
  };

  const handleFileImport = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (event) => {
          try {
              const json = event.target?.result as string;
              const plan = JSON.parse(json);
              if (plan.name && Array.isArray(plan.steps)) {
                  importPlan(plan, 'file');
              } else {
                  alert("Invalid file format.");
              }
          } catch (err) {
              alert("Failed to parse file.");
          }
      };
      reader.readAsText(file);
      e.target.value = ''; // Reset input
  };

  // Sort plans: Pinned first, then by original order
  const sortedPlans = useMemo(() => {
     return [...plans].sort((a, b) => {
         if (a.isPinned && !b.isPinned) return -1;
         if (!a.isPinned && b.isPinned) return 1;
         return 0; // Maintain existing order (drag/drop order)
     });
  }, [plans]);

  return (
    <>
      <ExerciseInfoModal 
          exerciseName={inspectExerciseName} 
          isVisible={!!inspectExerciseName} 
          onClose={() => setInspectExerciseName(null)} 
      />

      {infoPlan && <WorkoutInfoModal plan={infoPlan} onClose={() => setInfoPlan(null)} />}
      {sharePlan && <ShareModal plan={sharePlan} onClose={() => setSharePlan(null)} />}

