             )}

             {view === 'logs' && (
                 <WorkoutLog onBack={() => setView('list')} />
             )}
         </div>

         {/* Footer / User Actions */}
         {view === 'list' && (
             <div className="p-4 bg-gray-900 border-t border-gray-700 flex justify-between items-center gap-2 shrink-0 overflow-x-auto">
                 <div className="flex gap-2">
                     <label className="p-2 text-gray-400 hover:text-white hover:bg-gray-800 rounded-lg cursor-pointer" title="Import from file">
                         <input type="file" accept=".json" onChange={handleFileImport} className="hidden" />
                         <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" /></svg>
                     </label>
                     <button onClick={() => setView('logs')} className="p-2 text-gray-400 hover:text-white hover:bg-gray-800 rounded-lg" title="View Logs">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" /></svg>
                     </button>
