export const WorkoutMenu: React.FC<{ isOpen: boolean; setIsOpen: (open: boolean) => void }> = ({ isOpen, setIsOpen }) => {
  const { deletePlan, plans } = useWorkout();
  const [isPinned, setIsPinned] = useState(false);

  // View states
  const [isEditorOpen, setIsEditorOpen] = useState(false);
  const [editingPlan, setEditingPlan] = useState<WorkoutPlan | null>(null);
  const [isWarmupEditor, setIsWarmupEditor] = useState(false);

  const [isLogOpen, setIsLogOpen] = useState(false);

  // Modals
  const [planToDelete, setPlanToDelete] = useState<string | null>(null);
  const [inspectExerciseName, setInspectExerciseName] = useState<string | null>(null);
  const [infoPlan, setInfoPlan] = useState<WorkoutPlan | null>(null);
  const [isAiPlannerOpen, setIsAiPlannerOpen] = useState(false);

  const closeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Auto-close logic
  const handleClose = () => {
    setIsOpen(false);
    setIsPinned(false);
  };

  const handleMouseEnter = () => {
    if (closeTimerRef.current) {
      clearTimeout(closeTimerRef.current);
      closeTimerRef.current = null;
    }
  };

  const handleMouseLeave = () => {
    if (isOpen && !isPinned && !isEditorOpen && !isLogOpen && !isAiPlannerOpen) {
      closeTimerRef.current = setTimeout(() => {
        handleClose();
      }, 5000);
    }
  };

  useEffect(() => {
      if (!isOpen) {
          // Reset internal navigation when menu closes
          const t = setTimeout(() => {
             setIsEditorOpen(false);
             setIsLogOpen(false);
             setIsWarmupEditor(false);
             setEditingPlan(null);
          }, 500);
          return () => clearTimeout(t);
      }
  }, [isOpen]);

  // Swipe logic
  const touchStartX = useRef<number | null>(null);
  const touchEndX = useRef<number | null>(null);

  const handleTouchStart = (e: React.TouchEvent) => {
    touchStartX.current = e.touches[0].clientX;
  };
  const handleTouchMove = (e: React.TouchEvent) => {
    touchEndX.current = e.touches[0].clientX;
  };
  const handleTouchEnd = () => {
    if (touchStartX.current && touchEndX.current) {
        if (touchEndX.current - touchStartX.current < -50) { // Swipe left to close (since it's on left side)
             handleClose();
        }
    }
    touchStartX.current = null;
    touchEndX.current = null;
  };


  const handleDeleteConfirm = () => {
      if (planToDelete) {
          deletePlan(planToDelete);
          setPlanToDelete(null);
      }
  };

  const renderContent = () => {
      if (isEditorOpen) {
          return (
              <PlanEditor 
                  plan={editingPlan} 
                  onBack={() => setIsEditorOpen(false)} 
                  isWarmupEditor={isWarmupEditor}
              />
          );
      }
      if (isLogOpen) {
          return <WorkoutLog onBack={() => setIsLogOpen(false)} />;
      }
      return (
          <PlanList
              onSelectPlan={(plan) => {
                  if (typeof plan === 'string' && plan === '_warmup_') {
                       setIsWarmupEditor(true);
                       setEditingPlan(null);
                       setIsEditorOpen(true);
                  } else if (typeof plan !== 'string') {
                       setIsWarmupEditor(false);
                       setEditingPlan(plan);
                       setIsEditorOpen(true);
                  }
              }}
              onCreateNew={() => {
                  setIsWarmupEditor(false);
                  setEditingPlan(null);
                  setIsEditorOpen(true);
              }}
              onInitiateDelete={setPlanToDelete}
              onShowLog={() => setIsLogOpen(true)}
              onInspectExercise={setInspectExerciseName}
              onShowInfo={setInfoPlan}
              isPinned={isPinned}
              onTogglePin={() => setIsPinned(!isPinned)}
              onOpenAiPlanner={() => setIsAiPlannerOpen(true)}
          />
      );
  };

  return (
    <>
        <div className={`absolute top-4 left-4 menu-container group md:block hidden z-30`}>
          <button 
            onClick={() => isOpen ? handleClose() : setIsOpen(true)} 
            className="w-12 h-12 flex items-center justify-center rounded-full bg-gray-500/20 text-gray-400 hover:bg-gray-500/30 transition-opacity duration-1000 focus:outline-none opacity-0 group-hover:opacity-100"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg>
          </button>
        </div>

        {isOpen && (
            <div 
                className="fixed inset-0 bg-black/60 z-40"
                onClick={() => !isPinned && handleClose()}
            ></div>
        )}

        <div 
            className={`fixed top-0 left-0 h-full w-full max-w-sm bg-gray-800/90 backdrop-blur-md shadow-2xl z-50 transform transition-all ease-in-out ${isOpen ? 'duration-500 translate-x-0 opacity-100' : 'duration-[1500ms] -translate-x-full opacity-0 pointer-events-none'}`}
            onMouseEnter={handleMouseEnter}
            onMouseLeave={handleMouseLeave}
            onTouchStart={handleTouchStart}
            onTouchMove={handleTouchMove}
            onTouchEnd={handleTouchEnd}
        >
            <div className="p-6 overflow-y-auto h-full">
                {renderContent()}
            </div>

            {/* Modals rendered here to be above the menu content but handled within menu context */}
            <ExerciseInfoModal 
                exerciseName={inspectExerciseName} 
                isVisible={!!inspectExerciseName} 
                onClose={() => setInspectExerciseName(null)} 
            />

            {infoPlan && (
                <WorkoutInfoModal 
                    plan={infoPlan} 
                    onClose={() => setInfoPlan(null)} 
                />
            )}

            {planToDelete && (
                <ConfirmDeleteModal 
                    planName={plans.find(p => p.id === planToDelete)?.name || 'Plan'} 
                    onConfirm={handleDeleteConfirm} 
                    onCancel={() => setPlanToDelete(null)} 
                />
            )}

            {isAiPlannerOpen && (
                <AiPlannerModal onClose={() => setIsAiPlannerOpen(false)} />
            )}
        </div>
    </>
  );
};

import React, { Component, ErrorInfo, ReactNode } from 'react';
import { useLogger } from '../contexts/LoggingContext';

const CRASH_FLAG_KEY = 'app_crash_detected';

interface Props {
  children?: ReactNode;
  logError: (error: Error, componentStack: string) => void;
}

interface State {
  hasError: boolean;
}

/**
 * Internal class-based ErrorBoundary to use lifecycle methods.
 */
class ErrorBoundaryInternal extends React.Component<Props, State> {
  public state: State = { hasError: false };

  static getDerivedStateFromError(_: Error): State {
    return { hasError: true };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error("Uncaught error:", error, errorInfo);
    this.props.logError(error, errorInfo.componentStack || '');

    try {
        localStorage.setItem(CRASH_FLAG_KEY, 'true');
    } catch (e) {
        console.error("Could not set crash flag in localStorage:", e);
    }
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="h-screen w-screen bg-red-900 text-white flex flex-col items-center justify-center p-4 text-center">
            <h1 className="text-4xl font-bold">התרחשה שגיאה</h1>
            <p className="mt-4 text-lg">אפליקציית השעון נתקלה בבעיה בלתי צפויה.</p>
            <p className="mt-2 text-md text-red-200">
                נסה לרענן את הדף. אם הבעיה נמשכת, אנא פתח את תפריט ההגדרות, עבור לקטע 'מפתחים' והעתק את פרטי ניפוי השגיאות כדי לדווח על הבעיה.
            </p>
            <button
                onClick={() => window.location.reload()}
                className="mt-8 px-6 py-3 bg-red-600 rounded-lg font-semibold hover:bg-red-700 transition-colors"
            >
                רענן דף
            </button>
        </div>
      );
    }

    return this.props.children;
  }
}

