  const relevantLogs = useMemo(() => {
    return workoutHistory
        .filter(log => log.planIds?.includes(plan.id))
        .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [workoutHistory, plan.id]);

  const lastPerformedText = useMemo(() => {
    if (relevantLogs.length === 0) return null;

    const lastPerformed = new Date(relevantLogs[0].date);

    const now = new Date();
    // Reset time part for accurate day difference calculation
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const lastDay = new Date(lastPerformed.getFullYear(), lastPerformed.getMonth(), lastPerformed.getDate());

    const diffTime = today.getTime() - lastDay.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays === 0) return "בוצע היום";
    if (diffDays === 1) return "בוצע אתמול";
    if (diffDays < 7) return `בוצע לפני ${diffDays} ימים`;
    if (diffDays < 30) return `בוצע לפני ${Math.floor(diffDays/7)} שבועות`;

    return `בוצע לאחרונה: ${lastPerformed.toLocaleDateString('he-IL')}`;
  }, [relevantLogs]);

  const last7Performances = useMemo(() => {
    return relevantLogs.slice(0, 7).map(log => new Date(log.date));
  }, [relevantLogs]);


  useEffect(() => {
    // Automatically expand the active workout plan
    if (isActive) {
      setIsExpanded(true);
    }
  }, [isActive]);

  const displayedSteps = useMemo(() => {
    if (plan.executionMode === 'circuit') {
        return generateCircuitSteps(plan.steps);
    }
    return plan.steps;
  }, [plan.steps, plan.executionMode]);

  const getTotalDuration = (plan: WorkoutPlan) => {
    const totalSeconds = plan.steps.reduce((sum, step) => sum + (step.isRepBased ? 0 : step.duration), 0);
    if (isNaN(totalSeconds)) return '00:00';
    const minutes = Math.floor(totalSeconds / 60).toString().padStart(2, '0');
    const seconds = (totalSeconds % 60).toString().padStart(2, '0');
    return `${minutes}:${seconds}`;
  };

  const handleToggleMode = (e: React.MouseEvent) => {
    e.stopPropagation();
    const newMode = plan.executionMode === 'circuit' ? 'linear' : 'circuit';
    savePlan({ ...plan, executionMode: newMode });
  };

  const handleStop = (e: React.MouseEvent) => {
      e.stopPropagation();
      if (activeWorkout) {
        stopWorkout({ completed: false, durationMs: 0, finishedWorkout: activeWorkout });
      }
  }

  const handleEdit = (e: React.MouseEvent) => {
      e.stopPropagation();
      onSelectPlan(plan);
  };

  const handleExport = (e: React.MouseEvent) => {
    e.stopPropagation();
    try {
        const planJson = JSON.stringify(plan, null, 2);
        const blob = new Blob([planJson], { type: "application/json" });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        // Sanitize file name
        const fileName = `${plan.name.replace(/[^a-z0-9]/gi, '_').toLowerCase()}.json`;
        a.download = fileName;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    } catch (error) {
        console.error("Failed to export plan:", error);
        alert("Could not export the plan.");
    }
  };

  const handleCopyJson = (e: React.MouseEvent) => {
    e.stopPropagation();
    try {
        const planJson = JSON.stringify(plan, null, 2); // Pretty print
        navigator.clipboard.writeText(planJson).then(() => {
            showConfirmation("JSON Copied!");
        });
    } catch (error) {
        console.error("Failed to copy JSON:", error);
        alert("Could not copy JSON.");
    }
  };

  const handleDelete = (e: React.MouseEvent) => {
    e.stopPropagation();
    onInitiateDelete(plan.id);
  };

  const handleTogglePause = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (isCountdownPaused) {
      resumeStepCountdown();
    } else {
      pauseStepCountdown();
    }
  };

  const handleRestart = (e: React.MouseEvent) => {
      e.stopPropagation();
      restartCurrentStep();
  }

  const handleToggleLock = (e: React.MouseEvent) => {
    e.stopPropagation();
    savePlan({ ...plan, isLocked: !plan.isLocked });
  };

  const dragStyles = isDragTarget ? 'border-2 border-dashed border-blue-400' : 'border-2 border-transparent';
  const animationClass = isNewlyImported ? 'animate-glow' : '';

  return (
      <div 
          ref={setRef}
          className={`rounded-lg transition-all duration-300 ${isDraggable ? 'cursor-grab' : ''} ${dragStyles} ${animationClass} ${plan.isSmartPlan ? 'bg-purple-500/20' : 'bg-gray-700/50'}`}
          style={{ borderLeft: `5px solid ${plan.isSmartPlan ? '#a855f7' : (plan.color || 'transparent')}` }}
          draggable={isDraggable}
          onDragStart={(e) => onDragStart(e, index)}
          onDragOver={(e) => onDragOver(e, index)}
          onDrop={(e) => onDrop(e, index)}
          onDragEnd={onDragEnd}
          onDragLeave={onDragLeave}
      >
        <div className="p-3 cursor-pointer" onClick={() => setIsExpanded(!isExpanded)}>
          <div className="flex justify-between items-start gap-3">
            <div className="flex-1 min-w-0 flex items-start gap-3">
              {!activeWorkout && (
                  <input
                      type="checkbox"
                      checked={isSelected}
                      onChange={(e) => {
                          e.stopPropagation();
                          onToggleSelection(plan.id);
                      }}
                      onClick={(e) => e.stopPropagation()}
                      className="form-checkbox h-5 w-5 rounded bg-gray-600 border-gray-500 text-blue-500 focus:ring-blue-500 shrink-0 mt-1"
                      aria-label={`Select plan ${plan.name}`}
                  />
              )}
              <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    {plan.isSmartPlan && <span title="AI Generated Plan">✨</span>}
                    <h3 className="text-xl font-semibold text-white break-words" title={plan.name}>{plan.name}</h3>
                  </div>
                  <div className="text-sm text-gray-400 flex items-center">
                    <span className="truncate">
                        {plan.steps.length} steps, Total: {getTotalDuration(plan)}
                    </span>
                    {lastPerformedText && (
                    <>
                        <span className="mx-2 text-gray-500 shrink-0">|</span>
                        <div className="relative group flex items-center gap-1 shrink-0 whitespace-nowrap">
                            <span>{lastPerformedText}</span>
                            <button
                                onClick={(e) => { e.stopPropagation(); onShowInfo(plan); }}
                                className="text-gray-400 hover:text-white"
                                aria-label="Show workout statistics"
                                title="Show Stats"
                            >
                                <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" viewBox="0 0 20 20" fill="currentColor">
                                    <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
                                </svg>
                            </button>
                            {last7Performances.length > 0 && (
                                <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 w-max max-w-xs bg-gray-900 text-white text-sm rounded-lg shadow-lg p-2 z-10 opacity-0 group-hover:opacity-100 transition-opacity duration-200 pointer-events-none group-hover:pointer-events-auto">
                                    <h4 className="font-bold border-b border-gray-700 pb-1 mb-1 text-center">בוצע לאחרונה:</h4>
                                    <ul className="space-y-1">
                                        {last7Performances.map((date, index) => (
                                            <li key={index} className="text-xs text-gray-300 text-center">
                                                {date.toLocaleString('he-IL', { weekday: 'short', day: 'numeric', month: 'short', year: '2-digit', hour: '2-digit', minute: '2-digit' })}
                                            </li>
                                        ))}
                                    </ul>
                                    <div className="absolute top-full left-1/2 -translate-x-1/2 w-0 h-0 border-x-8 border-x-transparent border-t-8 border-t-gray-900"></div>
                                </div>
                            )}
                        </div>
                    </>
                    )}
                  </div>
              </div>
            </div>
          </div>

          <div className="flex gap-1 items-center mt-3 justify-end relative">
               {confirmationMessage && <span className="absolute -top-8 right-0 bg-gray-900 text-white text-xs px-2 py-1 rounded">{confirmationMessage}</span>}
               <button
                  onClick={(e) => {
                      e.stopPropagation();
                      onTogglePin(plan);
                  }}
                  className={`p-2 hover:bg-gray-600/50 rounded-full disabled:opacity-50 disabled:cursor-not-allowed ${plan.isPinned ? 'text-blue-400' : 'text-gray-300'}`}
                  aria-label={plan.isPinned ? "Unpin plan" : "Pin plan"}
                  title={plan.isPinned ? "בטל נעיצה" : "נעץ תוכנית (יופיע בראש הרשימה)"}
                  disabled={!!activeWorkout}
              >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                      <path fillRule="evenodd" d="M10 3a1 1 0 01.707.293l3 3a1 1 0 01-1.414 1.414L10 5.414 7.707 7.707a1 1 0 01-1.414-1.414l3-3A1 1 0 0110 3zm-3.707 9.293a1 1 0 011.414 0L10 14.586l2.293-2.293a1 1 0 011.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" transform="rotate(45 10 10)" />
                  </svg>
              </button>
               <button
                  onClick={handleToggleLock}
                  className={`p-2 hover:bg-gray-600/50 rounded-full disabled:opacity-50 disabled:cursor-not-allowed ${plan.isLocked ? 'text-yellow-400' : 'text-gray-300'}`}
                  aria-label={plan.isLocked ? "Un-lock plan" : "Lock plan"}
                  title={plan.isLocked ? "תוכנית נעולה (לחץ לפתיחה)" : "נעל תוכנית למניעת מחיקה"}
                  disabled={!!activeWorkout}
              >
                  {plan.isLocked ? (
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M5 9V7a5 5 0 0110 0v2a2 2 0 012 2v5a2 2 0 01-2 2H5a2 2 0 01-2-2v-5a2 2 0 012-2zm8-2v2H7V7a3 3 0 016 0z" clipRule="evenodd" /></svg>
                  ) : (
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path d="M10 2a5 5 0 00-5 5v2a2 2 0 00-2 2v5a2 2 0 002 2h10a2 2 0 002-2v-5a2 2 0 00-2-2V7a5 5 0 00-5-5zm0 9a3 3 0 100-6 3 3 0 000 6z" /></svg>
                  )}
              </button>
              <button
                  onClick={handleToggleMode}
                  className="p-2 text-gray-300 hover:text-white hover:bg-gray-600/50 rounded-full disabled:opacity-50 disabled:cursor-not-allowed"
                  aria-label={plan.executionMode === 'circuit' ? "Switch to Linear Mode" : "Switch to Circuit Mode"}
                  title={plan.executionMode === 'circuit' ? "Circuit Mode" : "Linear Mode"}
                  disabled={!!activeWorkout}
              >
                  {plan.executionMode === 'circuit' ? (
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M4 2a1 1 0 011 1v2.101a7.002 7.002 0 0111.601 2.566 1 1 0 11-1.885.666A5.002 5.002 0 005.999 7H9a1 1 0 110 2H4a1 1 0 01-1-1V3a1 1 0 011-1zm.008 9.057a1 1 0 011.276.61A5.002 5.002 0 0014.001 13H11a1 1 0 110-2h5a1 1 0 011 1v5a1 1 0 11-2 0v-2.101a7.002 7.002 0 01-11.601-2.566 1 1 0 01.61-1.276z" clipRule="evenodd" /></svg>
                  ) : (
                      <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M3 5a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zM3 10a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zM9 15a1 1 0 011-1h6a1 1 0 110 2h-6a1 1 0 01-1-1z" clipRule="evenodd" /></svg>
                  )}
              </button>
              <button
                  onClick={handleCopyJson}
                  className="p-2 text-gray-300 hover:text-white hover:bg-gray-600/50 rounded-full disabled:opacity-50 disabled:cursor-not-allowed"
                  aria-label="Copy plan as JSON"
                  title="Copy Plan as JSON"
                  disabled={!!activeWorkout}
              >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                    <path fillRule="evenodd" d="M12.316 3.051a1 1 0 01.633 1.265l-4 12a1 1 0 11-1.898-.632l4-12a1 1 0 011.265-.633zM5.707 6.293a1 1 0 010 1.414L3.414 10l2.293 2.293a1 1 0 11-1.414 1.414l-3-3a1 1 0 010-1.414l3-3a1 1 0 011.414 0zm8.586 0a1 1 0 011.414 0l3 3a1 1 0 010 1.414l-3 3a1 1 0 11-1.414-1.414L16.586 10l-2.293-2.293a1 1 0 010-1.414z" clipRule="evenodd" />
                  </svg>
              </button>
              <button
                onClick={(e) => {
                    e.stopPropagation();
                    onShare(plan);
                }}
                className="p-2 text-gray-300 hover:text-white hover:bg-gray-600/50 rounded-full disabled:opacity-50 disabled:cursor-not-allowed"
                aria-label="Share plan via link"
                title="Share Plan"
                disabled={!!activeWorkout}
              >
                  <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path d="M15 8a3 3 0 10-2.977-2.63l-4.94 2.47a3 3 0 100 4.319l4.94 2.47a3 3 0 10.895-1.789l-4.94-2.47a3.027 3.027 0 000-.74l4.94-2.47C13.456 7.68 14.19 8 15 8z" /></svg>
              </button>
              <button
                onClick={handleExport}
                className="p-2 text-gray-300 hover:text-white hover:bg-gray-600/50 rounded-full disabled:opacity-50 disabled:cursor-not-allowed"
                aria-label="Export plan to file"
                title="Export Plan"
                disabled={!!activeWorkout}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" /></svg>
              </button>
              <button
                onClick={handleEdit}
                className="p-2 text-gray-300 hover:text-white hover:bg-gray-600/50 rounded-full disabled:opacity-50 disabled:cursor-not-allowed"
                aria-label="Edit plan"
                title="Edit Plan"
                disabled={!!activeWorkout || plan.isLocked}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path d="M17.414 2.586a2 2 0 00-2.828 0L7 10.172V13h2.828l7.586-7.586a2 2 0 000-2.828z" /><path fillRule="evenodd" d="M2 6a2 2 0 012-2h4a1 1 0 010 2H4v10h10v-4a1 1 0 112 0v4a2 2 0 01-2 2H4a2 2 0 01-2-2V6z" clipRule="evenodd" /></svg>
              </button>
              <button
                onClick={handleDelete}
                className="p-2 text-gray-300 hover:text-red-500 hover:bg-red-500/10 rounded-full disabled:opacity-50 disabled:cursor-not-allowed"
                aria-label="Delete plan"
                title="Delete Plan"
                disabled={!!activeWorkout || plan.isLocked}
              >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M9 2a1 1 0 00-.894.553L7.382 4H4a1 1 0 000 2v10a2 2 0 002 2h8a2 2 0 002-2V6a1 1 0 100-2h-3.382l-.724-1.447A1 1 0 0011 2H9zM7 8a1 1 0 012 0v6a1 1 0 11-2 0V8zm4 0a1 1 0 012 0v6a1 1 0 11-2 0V8z" clipRule="evenodd" /></svg>
              </button>
          </div>

           {isActive ? (
               <div className="mt-3 grid grid-cols-3 gap-2">
                  <button onClick={handleStop} className="py-2 bg-red-600 text-white font-bold rounded-lg hover:bg-red-700 transition-colors text-sm">Stop</button>
                  <button onClick={handleTogglePause} className="py-2 bg-yellow-500 text-black font-bold rounded-lg hover:bg-yellow-600 transition-colors text-sm">{isCountdownPaused ? 'Resume' : 'Pause'}</button>
                  <button onClick={handleRestart} className="py-2 bg-gray-500 text-white font-bold rounded-lg hover:bg-gray-600 transition-colors text-sm" title="Restart current step">Restart</button>
               </div>
           ) : (
              <button 
                  onClick={(e) => { e.stopPropagation(); startWorkout([plan.id]); }}
                  className="w-full mt-3 py-2 bg-green-500 text-white font-bold rounded-lg hover:bg-green-600 transition-colors disabled:bg-gray-600 disabled:cursor-not-allowed"
                  disabled={!!activeWorkout}
              >
                  Start Workout
              </button>
           )}
        </div>
        {isExpanded && (
          <div className="border-t border-gray-600/50 px-3 pb-3 pt-2">
              <h4 className="text-sm font-semibold text-gray-300 mb-2">Steps:</h4>
              <ol className="text-gray-300 space-y-1">
                  {displayedSteps.map((step, index) => {
                      const isCurrent = isActive && step.id === currentStep?.id;
                      const color = step.type === 'exercise' ? exerciseColorMap.get(step.name) : 'transparent';

                      return (
                          <li 
                            key={`${step.id}-${index}`} 
                            className={`flex items-center gap-2 transition-all duration-200 rounded p-1 -m-1 ${isCurrent ? 'bg-blue-500/20 font-bold' : 'hover:bg-gray-600/50'}`}
                            title={getStepDisplayName(step)}
                            onClick={(e) => {
                              e.stopPropagation();
                              if (step.type === 'exercise') {
                                  onInspectExercise(step.name);
                              }
                            }}
                          >
                              <span className="w-1.5 h-4 rounded" style={{ backgroundColor: color }}></span>
                              <span className="truncate flex-1">{getStepDisplayName(step)} - <span className="text-gray-400 font-normal">{step.isRepBased ? `${step.reps} חזרות` : `${step.duration} שניות`}</span></span>
                          </li>
                      )
                  })}
              </ol>
          </div>
        )}
      </div>
  );
};

// --- Missing Components Implementation ---

const ConfirmDeleteModal: React.FC<{ planName: string, onConfirm: () => void, onCancel: () => void }> = ({ planName, onConfirm, onCancel }) => (
    <div className="fixed inset-0 bg-black/70 z-[101] flex items-center justify-center p-4" onClick={onCancel}>
        <div className="bg-gray-800 rounded-lg shadow-xl p-6 w-full max-w-sm" onClick={e => e.stopPropagation()}>
            <h3 className="text-xl font-bold text-white mb-2">Delete "{planName}"?</h3>
            <p className="text-gray-300 mb-6">Are you sure you want to delete this workout plan? This action cannot be undone.</p>
            <div className="flex justify-end gap-4">
                <button onClick={onCancel} className="px-4 py-2 rounded-md text-white bg-gray-600 hover:bg-gray-500 font-semibold">Cancel</button>
                <button onClick={onConfirm} className="px-4 py-2 rounded-md text-white bg-red-600 hover:bg-red-700 font-semibold">Delete</button>
            </div>
        </div>
    </div>
);

const AiPlannerModal: React.FC<{ onClose: () => void }> = ({ onClose }) => {
    const { importPlan } = useWorkout();
    const { settings } = useSettings();
    const { user } = useAuth();
    const [messages, setMessages] = useState<{ role: 'user' | 'model'; parts: { text: string }[] }[]>([]);
    const [input, setInput] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const scrollRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (scrollRef.current) {
            scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
        }
    }, [messages]);

    const handleSend = async () => {
        if (!input.trim() || isLoading) return;
        const userMsg = input.trim();
        setInput('');
        setMessages(prev => [...prev, { role: 'user', parts: [{ text: userMsg }] }]);
        setIsLoading(true);

        try {
            const profileContext = settings.userProfile ? JSON.stringify(settings.userProfile) : undefined;
            const responseText = await generateWorkoutPlan(messages, userMsg, profileContext);

            // Check if response contains a JSON block for a plan
            const jsonMatch = responseText.match(/```json\s*([\s\S]*?)\s*```/);
            if (jsonMatch) {
                try {
                    const planData = JSON.parse(jsonMatch[1]);
                    // Validate basic structure
                    if (planData.name && Array.isArray(planData.steps)) {
                        importPlan(planData, 'ai');
                        // Notify user in chat
                        setMessages(prev => [...prev, { role: 'model', parts: [{ text: responseText + "\n\n✅ Plan imported successfully!" }] }]);
                    } else {
                        setMessages(prev => [...prev, { role: 'model', parts: [{ text: responseText + "\n\n⚠️ The AI generated a plan, but it was missing required fields." }] }]);
                    }
                } catch (e) {
                    setMessages(prev => [...prev, { role: 'model', parts: [{ text: responseText + "\n\n⚠️ Failed to parse the AI generated plan." }] }]);
                }
            } else {
                setMessages(prev => [...prev, { role: 'model', parts: [{ text: responseText }] }]);
            }

        } catch (error) {
            setMessages(prev => [...prev, { role: 'model', parts: [{ text: "Error communicating with AI. Please try again." }] }]);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-black/80 z-[101] flex items-center justify-center p-4">
            <div className="bg-gray-900 w-full max-w-2xl h-[80vh] rounded-xl flex flex-col shadow-2xl border border-gray-700">
                <div className="p-4 border-b border-gray-700 flex justify-between items-center bg-gray-800 rounded-t-xl">
                    <h3 className="text-xl font-bold text-white flex items-center gap-2">
                        <span>✨</span> AI Workout Planner
                    </h3>
                    <button onClick={onClose} className="text-gray-400 hover:text-white">✕</button>
                </div>
                <div className="flex-1 overflow-y-auto p-4 space-y-4" ref={scrollRef}>
                    {messages.length === 0 && (
                        <div className="text-center text-gray-400 mt-10">
                            <p className="text-lg">Hi! I'm your AI Coach.</p>
                            <p className="text-sm mt-2">Tell me your goals, available equipment, and time constraints.</p>
                        </div>
                    )}
                    {messages.map((msg, idx) => (
                        <div key={idx} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                            <div className={`max-w-[80%] p-3 rounded-lg whitespace-pre-wrap ${msg.role === 'user' ? 'bg-blue-600 text-white' : 'bg-gray-700 text-gray-200'}`}>
                                {msg.parts[0].text}
                            </div>
                        </div>
                    ))}
                    {isLoading && <div className="text-gray-500 italic">AI is thinking...</div>}
                </div>
                <div className="p-4 border-t border-gray-700 bg-gray-800 rounded-b-xl flex gap-2">
                    <input 
                        type="text" 
                        className="flex-1 bg-gray-900 text-white border border-gray-600 rounded-lg p-2 focus:outline-none focus:border-blue-500"
                        placeholder="Type your request..."
                        value={input}
                        onChange={e => setInput(e.target.value)}
                        onKeyDown={e => e.key === 'Enter' && handleSend()}
                    />
                    <button 
                        onClick={handleSend}
                        disabled={isLoading || !input.trim()}
                        className="bg-blue-600 text-white px-4 py-2 rounded-lg font-semibold hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                        Send
                    </button>
                </div>
            </div>
        </div>
    );
};

const PlanList: React.FC<{
  onSelectPlan: (plan: WorkoutPlan | string) => void;
  onCreateNew: () => void;
  onInitiateDelete: (id: string) => void;
  onShowLog: () => void;
  onInspectExercise: (name: string) => void;
  onShowInfo: (plan: WorkoutPlan) => void;
  isPinned: boolean;
  onTogglePin: () => void;
  onOpenAiPlanner: () => void;
}> = ({ onSelectPlan, onCreateNew, onInitiateDelete, onShowLog, onInspectExercise, onShowInfo, isPinned, onTogglePin, onOpenAiPlanner }) => {
    const { plans, activeWorkout, reorderPlans, recentlyImportedPlanId, startWorkout } = useWorkout();
    const { authStatus, user, signIn, signOut } = useAuth();
    const { settings } = useSettings();
    const [selectedPlans, setSelectedPlans] = useState<string[]>([]);

    // Drag and Drop state
    const [dragSourceIndex, setDragSourceIndex] = useState<number | null>(null);
    const [dragTargetIndex, setDragTargetIndex] = useState<number | null>(null);

    const handleDragStart = (e: React.DragEvent, index: number) => {
        setDragSourceIndex(index);
        e.dataTransfer.effectAllowed = "move";
    };

    const handleDragOver = (e: React.DragEvent, index: number) => {
        e.preventDefault();
        setDragTargetIndex(index);
    };

    const handleDrop = (e: React.DragEvent, index: number) => {
        e.preventDefault();
        if (dragSourceIndex === null || dragSourceIndex === index) return;

        const newPlans = [...plans];
        const [removed] = newPlans.splice(dragSourceIndex, 1);
        newPlans.splice(index, 0, removed);

        reorderPlans(newPlans);
        setDragSourceIndex(null);
        setDragTargetIndex(null);
    };

    const handleDragEnd = () => {
        setDragSourceIndex(null);
        setDragTargetIndex(null);
    };

    const handleDragLeave = () => {
        setDragTargetIndex(null);
    };

    const togglePlanSelection = (planId: string) => {
        setSelectedPlans(prev => prev.includes(planId) ? prev.filter(id => id !== planId) : [...prev, planId]);
    };

    const startMultiSelectWorkout = () => {
        if (selectedPlans.length > 0) {
            startWorkout(selectedPlans);
            setSelectedPlans([]);
        }
    };

    // Warmup "pseudo-plan"
    const warmupPlan: WorkoutPlan = {
        id: '_warmup_',
        name: 'Warm-up Routine',
        steps: settings.warmupSteps,
        executionMode: 'linear',
        isLocked: true,
    };

    // Sort plans: pinned first
    const sortedPlans = [...plans].sort((a, b) => {
        if (a.isPinned && !b.isPinned) return -1;
        if (!a.isPinned && b.isPinned) return 1;
        return 0; // maintain original order (from reordering) within groups
    });

    return (
        <div className="flex flex-col h-full">
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h2 className="text-2xl font-bold text-white">Workouts</h2>
                    {authStatus === 'authenticated' && user && <p className="text-xs text-gray-400">Signed in as {user.email}</p>}
                </div>
                <div className="flex gap-2">
                    <button onClick={onTogglePin} className={`p-2 rounded-full hover:bg-gray-500/30 ${isPinned ? 'text-blue-400' : 'text-gray-400'}`} title={isPinned ? 'Unpin Menu' : 'Pin Menu'}>
                         <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M10 3a1 1 0 01.707.293l3 3a1 1 0 01-1.414 1.414L10 5.414 7.707 7.707a1 1 0 01-1.414-1.414l3-3A1 1 0 0110 3zm-3.707 9.293a1 1 0 011.414 0L10 14.586l2.293-2.293a1 1 0 011.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" clipRule="evenodd" transform="rotate(45 10 10)" /></svg>
                    </button>
                     <button onClick={onShowLog} className="p-2 rounded-full text-gray-400 hover:bg-gray-500/30" title="Workout Log">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01" /></svg>
                    </button>
                    {authStatus === 'unauthenticated' ? (
                        <button onClick={signIn} className="p-2 rounded-full text-gray-400 hover:bg-gray-500/30" title="Sign In with Google">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 16l-4-4m0 0l4-4m-4 4h14m-5 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h7a3 3 0 013 3v1" /></svg>
                        </button>
                    ) : (
                        <button onClick={signOut} className="p-2 rounded-full text-gray-400 hover:bg-gray-500/30" title="Sign Out">
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h7a3 3 0 013 3v1" /></svg>
                        </button>
                    )}
                </div>
            </div>

            <div className="flex gap-2 mb-4">
                 <button onClick={onOpenAiPlanner} className="flex-1 py-3 bg-gradient-to-r from-purple-600 to-blue-600 rounded-lg font-bold text-white shadow-lg hover:from-purple-700 hover:to-blue-700 transition-all flex items-center justify-center gap-2">
                    <span>✨</span> Create with AI
                </button>
                <button onClick={onCreateNew} className="flex-1 py-3 bg-blue-600 rounded-lg font-bold text-white shadow-lg hover:bg-blue-700 transition-colors flex items-center justify-center gap-2">
                     <span>+</span> Create Manually
                </button>
            </div>

            {selectedPlans.length > 0 && (
                <div className="mb-4 animate-fadeIn">
                     <button onClick={startMultiSelectWorkout} className="w-full py-2 bg-green-600 rounded-lg font-bold text-white shadow hover:bg-green-700 transition-colors">
                        Start Selected ({selectedPlans.length})
                    </button>
                </div>
            )}

            <div className="flex-grow space-y-3 overflow-y-auto pr-1">
                 {/* Warmup Section */}
                 <div className="mb-4">
                    <h3 className="text-gray-400 text-sm font-semibold uppercase tracking-wider mb-2">Pre-Workout</h3>
                    <PlanListItem
                        plan={warmupPlan}
                        onSelectPlan={() => onSelectPlan('_warmup_')}
                        onInitiateDelete={() => {}} // Cannot delete warmup
                        onInspectExercise={onInspectExercise}
                        onShowInfo={() => {}}
                        onShare={() => {}}
                        isSelected={false}
                        onToggleSelection={() => {}}
                        isDraggable={false}
                        onDragStart={() => {}}
                        onDragOver={() => {}}
                        onDrop={() => {}}
                        onDragEnd={() => {}}
                        onDragLeave={() => {}}
                        isDragTarget={false}
                        isNewlyImported={false}
                        index={-1}
                        setRef={() => {}}
                        onTogglePin={() => {}}
                    />
                 </div>

                 {/* Regular Plans */}
                 {plans.length === 0 ? (
                    <div className="text-center text-gray-500 mt-10">
                        <p>No workout plans yet.</p>
                        <p>Create one to get started!</p>
                    </div>
                 ) : (
                    sortedPlans.map((plan, index) => (
                        <PlanListItem
                            key={plan.id}
                            plan={plan}
                            index={index}
                            onSelectPlan={onSelectPlan}
                            onInitiateDelete={onInitiateDelete}
                            onInspectExercise={onInspectExercise}
                            onShowInfo={onShowInfo}
                            onShare={(p) => onSelectPlan(p)} // Re-using selection for now or direct share
                            isSelected={selectedPlans.includes(plan.id)}
                            onToggleSelection={togglePlanSelection}
                            isDraggable={!plan.isPinned} // Pinned items not draggable
                            onDragStart={handleDragStart}
                            onDragOver={handleDragOver}
                            onDrop={handleDrop}
                            onDragEnd={handleDragEnd}
                            onDragLeave={handleDragLeave}
                            isDragTarget={dragTargetIndex === index}
                            isNewlyImported={recentlyImportedPlanId === plan.id}
                            setRef={(el) => {}}
                            onTogglePin={() => {
                                const newPinnedState = !plan.isPinned;
                                const newPlans = plans.map(p => p.id === plan.id ? { ...p, isPinned: newPinnedState } : p);
                                reorderPlans(newPlans);
                            }}
                        />
                    ))
                 )}
            </div>
        </div>
    );
};

const PlanEditor: React.FC<{
    plan: WorkoutPlan | null;
    onBack: () => void;
    isWarmupEditor: boolean;
}> = ({ plan: initialPlan, onBack, isWarmupEditor }) => {
    const { savePlan } = useWorkout();
    const { settings, updateSettings } = useSettings();
    const [name, setName] = useState('');
    const [steps, setSteps] = useState<WorkoutStep[]>([]);
    const [executionMode, setExecutionMode] = useState<'linear' | 'circuit'>('linear');
    const [color, setColor] = useState('#3b82f6');
    const scrollRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (isWarmupEditor) {
            setName('חימום'); // Default name for display
            setSteps(settings.warmupSteps || []);
            setExecutionMode('linear');
        } else if (initialPlan) {
            setName(initialPlan.name);
            setSteps(initialPlan.steps);
            setExecutionMode(initialPlan.executionMode || 'linear');
            setColor(initialPlan.color || '#3b82f6');
        } else {
            setName('');
            setSteps([]);
            setExecutionMode('linear');
        }
    }, [initialPlan, isWarmupEditor, settings.warmupSteps]);

    const handleSave = () => {
        if (!name.trim()) {
            alert("Please enter a plan name.");
            return;
        }
        if (steps.length === 0) {
             alert("Please add at least one step.");
             return;
        }

        if (isWarmupEditor) {
            updateSettings({ warmupSteps: steps });
        } else {
            const newPlan: WorkoutPlan = {
                id: initialPlan?.id || Date.now().toString(),
                name,
                steps,
                executionMode,
                color,
                isPinned: initialPlan?.isPinned,
                isLocked: initialPlan?.isLocked
            };
            savePlan(newPlan);
        }
        onBack();
    };

    const addStep = (type: 'exercise' | 'rest') => {
        const newStep: WorkoutStep = {
            id: Date.now().toString(),
            name: type === 'exercise' ? 'New Exercise' : 'Rest',
            type,
            isRepBased: false,
            duration: type === 'rest' ? 30 : 60,
            reps: 10,
        };
        setSteps([...steps, newStep]);
        setTimeout(() => scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' }), 100);
    };

    const updateStep = (index: number, updates: Partial<WorkoutStep>) => {
        const newSteps = [...steps];
        newSteps[index] = { ...newSteps[index], ...updates };
        setSteps(newSteps);
    };

    const removeStep = (index: number) => {
        setSteps(steps.filter((_, i) => i !== index));
    };

    const moveStep = (index: number, direction: 'up' | 'down') => {
        if ((direction === 'up' && index === 0) || (direction === 'down' && index === steps.length - 1)) return;
        const newSteps = [...steps];
        const targetIndex = direction === 'up' ? index - 1 : index + 1;
        [newSteps[index], newSteps[targetIndex]] = [newSteps[targetIndex], newSteps[index]];
        setSteps(newSteps);
    };

    return (
        <div className="flex flex-col h-full">
             <div className="flex items-center mb-4 border-b border-gray-700 pb-2">
                <button onClick={onBack} className="p-2 mr-2 rounded-full hover:bg-gray-700 text-gray-400 hover:text-white">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" /></svg>
                </button>
                <h2 className="text-xl font-bold text-white">{isWarmupEditor ? 'Edit Warmup' : (initialPlan ? 'Edit Plan' : 'New Plan')}</h2>
            </div>

            <div className="flex-grow overflow-y-auto space-y-4 pr-1" ref={scrollRef}>
                {!isWarmupEditor && (
                    <div className="space-y-3 bg-gray-700/30 p-3 rounded-lg">
                        <div>
                            <label className="block text-sm text-gray-400 mb-1">Plan Name</label>
                            <input 
                                type="text" 
                                value={name} 
                                onChange={e => setName(e.target.value)} 
                                className="w-full bg-gray-900 text-white p-2 rounded border border-gray-600 focus:border-blue-500 outline-none" 
                                placeholder="My Awesome Workout"
                            />
                        </div>
                        <div className="flex gap-4">
                            <div className="flex-1">
                                <label className="block text-sm text-gray-400 mb-1">Mode</label>
                                <div className="flex bg-gray-900 rounded p-1 border border-gray-600">
                                    <button 
                                        onClick={() => setExecutionMode('linear')}
                                        className={`flex-1 py-1 rounded text-sm ${executionMode === 'linear' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
                                    >
                                        Linear
                                    </button>
                                    <button 
                                        onClick={() => setExecutionMode('circuit')}
                                        className={`flex-1 py-1 rounded text-sm ${executionMode === 'circuit' ? 'bg-blue-600 text-white' : 'text-gray-400 hover:text-white'}`}
                                    >
                                        Circuit
                                    </button>
                                </div>
                            </div>
                             <div className="flex-1">
                                <label className="block text-sm text-gray-400 mb-1">Color</label>
                                <input type="color" value={color} onChange={e => setColor(e.target.value)} className="w-full h-9 bg-transparent cursor-pointer rounded" />
                            </div>
                        </div>
                    </div>
                )}

                <div className="space-y-2">
                    {steps.map((step, index) => (
                        <div key={step.id} className="bg-gray-700/50 p-3 rounded-lg border border-gray-600 flex flex-col gap-2">
                            <div className="flex justify-between items-center">
                                <div className="flex items-center gap-2">
                                     <span className={`w-2 h-2 rounded-full ${step.type === 'exercise' ? 'bg-green-500' : 'bg-yellow-500'}`}></span>
                                     <span className="text-xs text-gray-400 uppercase font-bold">{step.type}</span>
                                </div>
                                <div className="flex gap-1">
                                     <button onClick={() => moveStep(index, 'up')} className="p-1 hover:bg-gray-600 rounded text-gray-400" disabled={index === 0}>↑</button>
                                     <button onClick={() => moveStep(index, 'down')} className="p-1 hover:bg-gray-600 rounded text-gray-400" disabled={index === steps.length - 1}>↓</button>
                                     <button onClick={() => removeStep(index)} className="p-1 hover:bg-red-500/20 text-red-400 rounded">✕</button>
                                </div>
                            </div>

                            <input 
                                type="text" 
                                value={step.name} 
                                onChange={e => updateStep(index, { name: e.target.value })} 
                                className="bg-gray-900 text-white p-2 rounded border border-gray-600 text-sm focus:border-blue-500 outline-none"
                            />

                            <div className="flex gap-2 items-center">
                                {step.type === 'exercise' && (
                                    <button 
                                        onClick={() => updateStep(index, { isRepBased: !step.isRepBased })}
                                        className={`px-2 py-1 text-xs rounded border border-gray-500 ${step.isRepBased ? 'bg-blue-600 border-blue-600 text-white' : 'text-gray-400'}`}
                                    >
                                        {step.isRepBased ? 'Reps' : 'Time'}
                                    </button>
                                )}

                                {step.isRepBased ? (
                                    <div className="flex items-center gap-2 flex-1">
                                        <span className="text-sm text-gray-400">Reps:</span>
                                        <HoverNumberInput 
                                            value={step.reps} 
                                            onChange={(val) => updateStep(index, { reps: val })} 
                                            min={1} 
                                            className="w-16 bg-gray-900 text-white text-center p-1 rounded border border-gray-600"
                                        />
                                    </div>
                                ) : (
                                    <div className="flex items-center gap-2 flex-1">
                                        <span className="text-sm text-gray-400">Secs:</span>
                                        <HoverNumberInput 
                                            value={step.duration} 
                                            onChange={(val) => updateStep(index, { duration: val })} 
                                            min={1} 
                                            className="w-16 bg-gray-900 text-white text-center p-1 rounded border border-gray-600"
                                        />
                                    </div>
                                )}
                            </div>
                        </div>
                    ))}
                </div>

                 <div className="flex gap-2 pt-2">
                    <button onClick={() => addStep('exercise')} className="flex-1 py-2 bg-gray-700 hover:bg-gray-600 text-white rounded border border-dashed border-gray-500 flex items-center justify-center gap-2">
                        + Exercise
                    </button>
                    <button onClick={() => addStep('rest')} className="flex-1 py-2 bg-gray-700 hover:bg-gray-600 text-white rounded border border-dashed border-gray-500 flex items-center justify-center gap-2">
                        + Rest
                    </button>
                </div>
            </div>

            <div className="mt-4 pt-4 border-t border-gray-700">
                <button onClick={handleSave} className="w-full py-3 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-lg shadow-lg">
                    Save Plan
                </button>
            </div>
        </div>
    );
};

export const WorkoutMenu: React.FC<{ isOpen: boolean; setIsOpen: (open: boolean) => void }> = ({ isOpen, setIsOpen }) => {
  const { deletePlan, plans } = useWorkout();
  const [isPinned, setIsPinned] = useState(false);

  // View states
  const [isEditorOpen, setIsEditorOpen] = useState(false);
  const [editingPlan, setEditingPlan] = useState<WorkoutPlan | null>(null);
  const [isWarmupEditor, setIsWarmupEditor] = useState(false);

  const [isLogOpen, setIsLogOpen] = useState(false);

  // Modals
  const [planToDelete, setPlanToDelete] = useState<string | null>(null);
  const [inspectExerciseName, setInspectExerciseName] = useState<string | null>(null);
  const [infoPlan, setInfoPlan] = useState<WorkoutPlan | null>(null);
  const [isAiPlannerOpen, setIsAiPlannerOpen] = useState(false);

  const closeTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  // Auto-close logic
  const handleClose = () => {
    setIsOpen(false);
    setIsPinned(false);
  };

  const handleMouseEnter = () => {
    if (closeTimerRef.current) {
      clearTimeout(closeTimerRef.current);
      closeTimerRef.current = null;
    }
  };

  const handleMouseLeave = () => {
    if (isOpen && !isPinned && !isEditorOpen && !isLogOpen && !isAiPlannerOpen) {
      closeTimerRef.current = setTimeout(() => {
        handleClose();
      }, 5000);
    }
  };

  useEffect(() => {
      if (!isOpen) {
          // Reset internal navigation when menu closes
          const t = setTimeout(() => {
             setIsEditorOpen(false);
             setIsLogOpen(false);
             setIsWarmupEditor(false);
             setEditingPlan(null);
          }, 500);
          return () => clearTimeout(t);
      }
  }, [isOpen]);

  // Swipe logic
  const touchStartX = useRef<number | null>(null);
  const touchEndX = useRef<number | null>(null);

  const handleTouchStart = (e: React.TouchEvent) => {
    touchStartX.current = e.touches[0].clientX;
  };
  const handleTouchMove = (e: React.TouchEvent) => {
    touchEndX.current = e.touches[0].clientX;
  };
  const handleTouchEnd = () => {
    if (touchStartX.current && touchEndX.current) {
        if (touchEndX.current - touchStartX.current < -50) { // Swipe left to close (since it's on left side)
             handleClose();
        }
    }
    touchStartX.current = null;
    touchEndX.current = null;
  };


  const handleDeleteConfirm = () => {
      if (planToDelete) {
          deletePlan(planToDelete);
          setPlanToDelete(null);
      }
  };

  const renderContent = () => {
      if (isEditorOpen) {
          return (
              <PlanEditor 
                  plan={editingPlan} 
                  onBack={() => setIsEditorOpen(false)} 
                  isWarmupEditor={isWarmupEditor}
              />
          );
      }
      if (isLogOpen) {
          return <WorkoutLog onBack={() => setIsLogOpen(false)} />;
      }
      return (
          <PlanList
              onSelectPlan={(plan) => {
                  if (typeof plan === 'string' && plan === '_warmup_') {
                       setIsWarmupEditor(true);
                       setEditingPlan(null);
                       setIsEditorOpen(true);
                  } else if (typeof plan !== 'string') {
                       setIsWarmupEditor(false);
                       setEditingPlan(plan);
                       setIsEditorOpen(true);
                  }
              }}
              onCreateNew={() => {
                  setIsWarmupEditor(false);
                  setEditingPlan(null);
                  setIsEditorOpen(true);
              }}
              onInitiateDelete={setPlanToDelete}
              onShowLog={() => setIsLogOpen(true)}
              onInspectExercise={setInspectExerciseName}
              onShowInfo={setInfoPlan}
              isPinned={isPinned}
              onTogglePin={() => setIsPinned(!isPinned)}
              onOpenAiPlanner={() => setIsAiPlannerOpen(true)}
          />
      );
  };

  return (
    <>
        <div className={`absolute top-4 left-4 menu-container group z-30`}>
          <button 
            onClick={() => isOpen ? handleClose() : setIsOpen(true)} 
            className="w-12 h-12 flex items-center justify-center rounded-full bg-gray-500/20 text-gray-400 hover:bg-gray-500/30 transition-opacity duration-1000 focus:outline-none opacity-0 group-hover:opacity-100"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 6h16M4 12h16M4 18h16" /></svg>
          </button>
        </div>

        {isOpen && (
            <div 
                className="fixed inset-0 bg-black/60 z-40"
                onClick={() => !isPinned && handleClose()}
            ></div>
        )}

        <div 
            className={`fixed top-0 left-0 h-full w-full max-w-sm bg-gray-800/90 backdrop-blur-md shadow-2xl z-50 transform transition-all ease-in-out ${isOpen ? 'duration-500 translate-x-0 opacity-100' : 'duration-[1500ms] -translate-x-full opacity-0 pointer-events-none'}`}
            onMouseEnter={handleMouseEnter}
            onMouseLeave={handleMouseLeave}
            onTouchStart={handleTouchStart}
            onTouchMove={handleTouchMove}
            onTouchEnd={handleTouchEnd}
        >
            <div className="p-6 overflow-y-auto h-full">
                {renderContent()}
            </div>

            {/* Modals rendered here to be above the menu content but handled within menu context */}
            <ExerciseInfoModal 
                exerciseName={inspectExerciseName} 
                isVisible={!!inspectExerciseName} 
                onClose={() => setInspectExerciseName(null)} 
            />

            {infoPlan && (
                <WorkoutInfoModal 
                    plan={infoPlan} 
                    onClose={() => setInfoPlan(null)} 
                />
            )}

            {planToDelete && (
                <ConfirmDeleteModal 
                    planName={plans.find(p => p.id === planToDelete)?.name || 'Plan'} 
                    onConfirm={handleDeleteConfirm} 
                    onCancel={() => setPlanToDelete(null)} 
                />
            )}

            {isAiPlannerOpen && (
                <AiPlannerModal onClose={() => setIsAiPlannerOpen(false)} />
            )}
        </div>
    </>
  );
};

