const AiProfilePanel: React.FC<{ isOpen: boolean; onClose: () => void; }> = ({ isOpen, onClose }) => {
    const { settings, updateSettings } = useSettings();
    const [newEquipment, setNewEquipment] = useState('');
    const { userProfile } = settings;

    const age = useMemo(() => {
        if (!userProfile?.birthDate) return null;
        try {
            const birthDate = new Date(userProfile.birthDate);
            const today = new Date();
            let age = today.getFullYear() - birthDate.getFullYear();
            const m = today.getMonth() - birthDate.getMonth();
            if (m < 0 || (m === 0 && today.getDate() < birthDate.getDate())) {
                age--;
            }
            return age > 0 ? age : null;
        } catch {
            return null;
        }
    }, [userProfile?.birthDate]);

    const handleProfileUpdate = (field: keyof NonNullable<typeof userProfile>, value: any) => {
        updateSettings({
            userProfile: {
                ...userProfile,
                [field]: value,
            },
        });
    };

    const handleAddEquipment = () => {
        const trimmedName = newEquipment.trim();
        if (trimmedName === '') return;
        const currentEquipment = userProfile?.equipment || [];
        if (currentEquipment.some(e => e.name.toLowerCase() === trimmedName.toLowerCase())) return;

        handleProfileUpdate('equipment', [...currentEquipment, { name: trimmedName, available: true }]);
        setNewEquipment('');
    };

    const handleRemoveEquipment = (nameToRemove: string) => {
        handleProfileUpdate('equipment', (userProfile?.equipment || []).filter(e => e.name !== nameToRemove));
    };

    const handleToggleEquipment = (nameToToggle: string) => {
        handleProfileUpdate('equipment', (userProfile?.equipment || []).map(e => 
            e.name === nameToToggle ? { ...e, available: !e.available } : e
        ));
    };

    const FitnessButton: React.FC<{level: 'beginner' | 'intermediate' | 'advanced'}> = ({ level }) => {
        const isActive = userProfile?.fitnessLevel === level;
        return (
            <button 
                onClick={() => handleProfileUpdate('fitnessLevel', level)}
                className={`flex-1 py-2 text-sm font-semibold rounded-md transition-colors ${isActive ? 'bg-blue-600 text-white' : 'bg-gray-600 hover:bg-gray-500'}`}
            >
                {level.charAt(0).toUpperCase() + level.slice(1)}
            </button>
        );
    };

    return (
        <>
            <div 
                className={`fixed inset-0 bg-black/50 z-[101] transition-opacity duration-300 ${isOpen ? 'opacity-100' : 'opacity-0 pointer-events-none'}`} 
                onClick={onClose}
            />
            <div 
                className={`fixed top-0 right-0 h-full w-full max-w-sm bg-gray-800 shadow-2xl z-[102] transform transition-transform duration-300 flex flex-col ${isOpen ? 'translate-x-0' : 'translate-x-full'}`}
                dir="rtl"
            >
                <div className="flex justify-between items-center p-4 border-b border-gray-700 shrink-0">
                    <h3 className="text-xl font-bold text-white">הפרופיל שלי</h3>
                    <button onClick={onClose} className="p-2 rounded-full hover:bg-gray-700">
                         <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                </div>
                <div className="p-4 space-y-6 overflow-y-auto flex-grow">
                    <div>
                        <label className="text-sm font-semibold text-gray-300">תאריך לידה</label>
                        <div className="flex items-center gap-4 mt-1">
                            <input 
                                type="date"
                                value={userProfile?.birthDate || ''}
                                onChange={e => handleProfileUpdate('birthDate', e.target.value)}
                                className="bg-gray-700 p-2 rounded-md text-white w-full"
                            />
                            {age && <span className="text-lg font-bold text-white shrink-0">{age}</span>}
                        </div>
                    </div>
                    <div>
                        <label className="text-sm font-semibold text-gray-300">רמת כושר</label>
                        <div className="flex gap-2 mt-1">
                            <FitnessButton level="beginner" />
                            <FitnessButton level="intermediate" />
                            <FitnessButton level="advanced" />
                        </div>
                    </div>
                     <div>
                        <label className="text-sm font-semibold text-gray-300">הציוד שלי</label>
                        <div className="flex gap-2 mt-1">
                            <input 
                                type="text"
                                value={newEquipment}
                                onChange={e => setNewEquipment(e.target.value)}
                                onKeyPress={e => e.key === 'Enter' && handleAddEquipment()}
                                placeholder="הוסף ציוד..."
                                className="flex-grow bg-gray-700 p-2 rounded-md text-white"
                            />
                            <button onClick={handleAddEquipment} className="px-4 py-2 bg-blue-600 rounded-md font-semibold hover:bg-blue-700">+</button>
                        </div>
                        <div className="mt-3 space-y-2 max-h-60 overflow-y-auto pr-2">
                            {(userProfile?.equipment || []).map(item => (
                                <div key={item.name} className="flex items-center bg-gray-700/50 p-2 rounded-md">
                                    <input 
                                        type="checkbox"
                                        id={`equip-${item.name}`}
                                        checked={item.available}
                                        onChange={() => handleToggleEquipment(item.name)}
                                        className="w-5 h-5 bg-gray-600 border-gray-500 text-blue-500 rounded focus:ring-blue-500"
                                    />
                                    <label htmlFor={`equip-${item.name}`} className="flex-grow mx-3 text-white truncate cursor-pointer">{item.name}</label>
                                    <button onClick={() => handleRemoveEquipment(item.name)} className="p-1 text-gray-400 hover:text-red-500">
                                        <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                                    </button>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            </div>
        </>
    );
};


const AiPlannerModal: React.FC<{
    onClose: () => void;
}> = ({ onClose }) => {
    type ChatPart = { text: string; isPlanLink?: boolean; planName?: string };
    type ChatMessage = { role: 'user' | 'model'; parts: ChatPart[] };

    const { importPlan } = useWorkout();
    const { settings } = useSettings();
    const AI_CHAT_HISTORY_KEY = 'sportsClockAiChatHistory_v2';

    const [messages, setMessages] = useState<ChatMessage[]>(() => {
        try {
            const saved = localStorage.getItem(AI_CHAT_HISTORY_KEY);
            return saved ? JSON.parse(saved) : [];
        } catch { return []; }
    });
    const [input, setInput] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    // --- New State for AI Model ---
    const [modelPreference, setModelPreference] = useState<'smart' | 'speed'>('smart');
    const [showModelSelector, setShowModelSelector] = useState(false);
    // Fix: Properly declare state for profile panel
    const [isProfileOpen, setIsProfileOpen] = useState(false);
    const messagesEndRef = useRef<HTMLDivElement>(null);
    const textareaRef = useRef<HTMLTextAreaElement>(null);

    useEffect(() => {
        localStorage.setItem(AI_CHAT_HISTORY_KEY, JSON.stringify(messages));
        messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
    }, [messages]);

    useEffect(() => {
        const textarea = textareaRef.current;
        if (textarea) {
            textarea.style.height = 'auto';
            const scrollHeight = textarea.scrollHeight;

            const computedStyle = getComputedStyle(textarea);
            const lineHeight = parseFloat(computedStyle.lineHeight) || 24; // Fallback
            const paddingTop = parseFloat(computedStyle.paddingTop);
            const paddingBottom = parseFloat(computedStyle.paddingBottom);
            const maxHeight = (lineHeight * 5) + paddingTop + paddingBottom;

            textarea.style.height = `${Math.min(scrollHeight, maxHeight)}px`;
            textarea.style.overflowY = scrollHeight > maxHeight ? 'auto' : 'hidden';
        }
    }, [input]);

    const handleNewChat = () => {
        setMessages([]);
        localStorage.removeItem(AI_CHAT_HISTORY_KEY);
    };

    const handleSend = async () => {
        if (!input.trim() || isLoading) return;

        const userMessage: ChatMessage = { role: 'user', parts: [{ text: input }] };
        const newMessages = [...messages, userMessage];
        setMessages(newMessages);
        setInput('');
        setIsLoading(true);

        let profileContext = '';
        if (settings.userProfile) {
            const { userProfile } = settings;
            const profileParts = [];
            if (userProfile.birthDate) {
                const birthDate = new Date(userProfile.birthDate);
                const age = new Date().getFullYear() - birthDate.getFullYear();
                if (age > 0 && age < 120) profileParts.push(`Age: ${age}`);
            }
            if (userProfile.fitnessLevel) {
                profileParts.push(`Fitness Level: ${userProfile.fitnessLevel}`);
            }
            const availableEquipment = userProfile.equipment?.filter(e => e.available).map(e => e.name);
            if (availableEquipment && availableEquipment.length > 0) {
                profileParts.push(`Available Equipment: ${availableEquipment.join(', ')}`);
            }
            if (profileParts.length > 0) {
                profileContext = profileParts.join('; ');
            }
        }

        try {
const responseText = await generateWorkoutPlan(messages, input, profileContext, modelPreference);            
            // The service now returns a user-friendly error string, prefixed with "Error:".
            if (responseText.startsWith('Error: ')) {
                const userFriendlyMessage = responseText.substring('Error: '.length);
                setMessages(prev => [...prev, { role: 'model', parts: [{ text: userFriendlyMessage }] }]);
                return; // Stop further processing
            }


            // --- Success Path ---
            const jsonRegex = /```json\s*([\s\S]*?)\s*```/;
            const match = responseText.match(jsonRegex);
            const conversationalText = responseText.replace(jsonRegex, '').trim();

            let finalMessages = [...newMessages];

            if (conversationalText) {
                finalMessages.push({ role: 'model', parts: [{ text: conversationalText }]});
            }

            if (match && match[1]) {
                try {
                    const planJson = JSON.parse(match[1]);
                    planJson.isSmartPlan = true;
                    planJson.color = '#a855f7';

                    importPlan(planJson, 'ai');

                    finalMessages.push({ role: 'model', parts: [{ text: '', isPlanLink: true, planName: planJson.name }]});

                } catch (e) {
                    console.error("Failed to parse AI-generated JSON:", e);
                    finalMessages.push({ role: 'model', parts: [{ text: "I tried to generate a plan, but there was an error. Could you please clarify your request?" }] });
                }
            } else if (!conversationalText) {
                // If there's no conversational text and no JSON, it's probably just a text response.
                 finalMessages.push({ role: 'model', parts: [{ text: responseText }]});
            }

            setMessages(finalMessages);

        } catch (error) {
            console.error("AI Planner error:", error);
            const errorMessage = error instanceof Error ? error.message : "Sorry, something went wrong.";
            setMessages([...newMessages, { role: 'model', parts: [{ text: errorMessage }] }]);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <div className="fixed inset-0 bg-gray-900/90 z-[100] flex flex-col p-4" aria-modal="true" role="dialog">
            <AiProfilePanel isOpen={isProfileOpen} onClose={() => setIsProfileOpen(false)} />
             <div className="flex justify-between items-center mb-4 text-white">
                <button onClick={() => setIsProfileOpen(true)} title="הפרופיל שלי" className="p-2 rounded-full hover:bg-gray-700">
                    <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor">
                        <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-6-3a2 2 0 11-4 0 2 2 0 014 0zm-2 4a5 5 0 00-4.546 2.916A5.986 5.986 0 0010 16a5.986 5.986 0 004.546-2.084A5 5 0 0010 11z" clipRule="evenodd" />
                    </svg>
                </button>
                <h2 className="text-xl font-bold flex items-center gap-2">✨ AI Workout Planner</h2>
                <div className="flex items-center gap-2">
                    <button onClick={handleNewChat} title="Start a new chat" className="p-2 rounded-full hover:bg-gray-700">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor"><path fillRule="evenodd" d="M4 2a1 1 0 011 1v2.101a7.002 7.002 0 0111.601 2.566 1 1 0 11-1.885.666A5.002 5.002 0 005.999 7H9a1 1 0 110 2H4a1 1 0 01-1-1V3a1 1 0 011-1zm.008 9.057a1 1 0 011.276.61A5.002 5.002 0 0014.001 13H11a1 1 0 110-2h5a1 1 0 011 1v5a1 1 0 11-2 0v-2.101a7.002 7.002 0 01-11.601-2.566 1 1 0 01.61-1.276z" clipRule="evenodd" /></svg>
                    </button>
                    <button onClick={onClose} className="p-2 rounded-full hover:bg-gray-700">
                        <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                    </button>
                </div>
            </div>
            <div className="flex-grow overflow-y-auto mb-4 space-y-4 pr-2">
                 {messages.length === 0 && (
                    <div className="text-center text-gray-400 p-8" dir="rtl">
                        <p className="text-lg">ברוכים הבאים למתכנן האימונים החכם!</p>
                        <p className="mt-2">תאר את האימון שברצונך לבנות. לדוגמה:</p>
                        <em className="block mt-2">"צור לי תוכנית אימון למתחילים באורך 20 דקות לכל הגוף."</em>
                    </div>
                )}
                {messages.map((msg, index) => (
                    <div key={index} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                        <div className={`max-w-prose p-3 rounded-lg ${msg.role === 'user' ? 'bg-blue-600 text-white' : 'bg-gray-700 text-gray-200'}`}>
                            {msg.parts.map((part, partIndex) => 
                                part.isPlanLink ? (
                                    <div key={partIndex} dir="auto">
                                        <p>הוספתי את תוכנית "{part.planName}" לרשימה שלך.</p>
                                        <button onClick={onClose} className="mt-2 font-bold text-blue-300 hover:text-blue-200 underline">
                                            הצג תוכנית
                                        </button>
                                    </div>
                                ) : (
                                    <p key={partIndex} className="whitespace-pre-wrap" dir="auto">{part.text}</p>
                                )
                            )}
                        </div>
                    </div>
                ))}
                {isLoading && (
                     <div className="flex justify-start">
                        <div className="max-w-sm p-3 rounded-lg bg-gray-700 text-gray-200">
                            <div className="flex items-center gap-3">
                                <div className="flex items-center gap-2">
                                    <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{animationDelay: '0s'}}></div>
                                    <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{animationDelay: '0.1s'}}></div>
                                    <div className="w-2 h-2 bg-gray-400 rounded-full animate-bounce" style={{animationDelay: '0.2s'}}></div>
                                </div>
                                <span className="text-sm italic text-gray-400">בונה לך את האימון המושלם, כמה רגעים...</span>
                            </div>
                        </div>
                    </div>
                )}
                 <div ref={messagesEndRef} />
            </div>
{/* --- New Input Area with Model Selector (Adapted) --- */}
            <div className="flex gap-2 items-end bg-gray-900/50 p-2 rounded-xl border-t border-gray-700 relative">
                {/* Popup Menu */}
                {showModelSelector && (
                    <div className="absolute bottom-16 left-0 bg-gray-800 border border-gray-700 rounded-xl shadow-2xl p-2 w-56 z-50 animate-in fade-in slide-in-from-bottom-2">
                        <div className="text-xs text-gray-500 mb-2 px-2 uppercase tracking-wider font-bold">בחר מודל</div>
                        <button
                            onClick={() => { setModelPreference('smart'); setShowModelSelector(false); }}
                            className={`w-full text-left px-3 py-3 rounded-lg text-sm flex items-center gap-3 transition-colors ${modelPreference === 'smart' ? 'bg-indigo-600/20 text-indigo-300 border border-indigo-500/30' : 'text-gray-300 hover:bg-gray-700'}`}
                        >
                            <span className="text-xl">🧠</span>
                            <div className="text-right flex-1">
                                <div className="font-bold">Smart Pro</div>
                                <div className="text-[10px] opacity-70">חשיבה עמוקה ודיוק</div>
                            </div>
                        </button>
                        <button
                            onClick={() => { setModelPreference('speed'); setShowModelSelector(false); }}
                            className={`w-full text-left px-3 py-3 rounded-lg text-sm flex items-center gap-3 mt-1 transition-colors ${modelPreference === 'speed' ? 'bg-emerald-600/20 text-emerald-300 border border-emerald-500/30' : 'text-gray-300 hover:bg-gray-700'}`}
                        >
                            <span className="text-xl">⚡</span>
                            <div className="text-right flex-1">
                                <div className="font-bold">Flash Speed</div>
                                <div className="text-[10px] opacity-70">מהיר וחסכוני</div>
                            </div>
                        </button>
                    </div>
                )}

                {/* Model Toggle Button */}
                <button
                    onClick={() => setShowModelSelector(!showModelSelector)}
                    className={`p-3 mb-1 rounded-xl transition-all border shrink-0 ${
                        modelPreference === 'smart' 
                        ? 'bg-indigo-500/10 text-indigo-400 border-indigo-500/30 hover:bg-indigo-500/20' 
                        : 'bg-emerald-500/10 text-emerald-400 border-emerald-500/30 hover:bg-emerald-500/20'
                    }`}
                    title="בחר מודל AI"
                >
                    {modelPreference === 'smart' ? '🧠' : '⚡'}
                </button>

                {/* Textarea Input */}
                <textarea
                    ref={textareaRef}
                    rows={1}
                    value={input}
                    onChange={(e) => setInput(e.target.value)}
                    onKeyPress={(e) => {
                        if (e.key === 'Enter' && !e.shiftKey) {
                            e.preventDefault();
                            handleSend();
                        }
                    }}
                    placeholder={modelPreference === 'smart' ? "שאל את המאמן (מודל חכם)..." : "בקשה מהירה..."}
                    className="flex-grow bg-gray-800 text-white p-3 rounded-lg focus:outline-none focus:ring-2 focus:ring-indigo-500/50 resize-none max-h-32 overflow-y-auto"
                    dir="rtl"
                    disabled={isLoading}
                />

                {/* Send Button (Icon) */}
                <button
                    onClick={handleSend}
                    disabled={isLoading || !input.trim()}
                    className="p-3 mb-1 bg-indigo-600 text-white rounded-xl hover:bg-indigo-500 disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-lg shadow-indigo-500/20 shrink-0"
                >
                    {isLoading ? (
                        <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin" />
                    ) : (
                        // Send Icon
                        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-5 h-5 transform rotate-180">
                            <path d="M3.478 2.405a.75.75 0 00-.926.94l2.432 7.905H13.5a.75.75 0 010 1.5H4.984l-2.432 7.905a.75.75 0 00.926.94 60.519 60.519 0 0018.445-8.986.75.75 0 000-1.218A60.517 60.517 0 003.478 2.405z" />
                        </svg>
                    )}
                </button>
            </div>        </div>
    );
};

const ImportTextModal: React.FC<{ onImport: (text: string) => void; onCancel: () => void; }> = ({ onImport, onCancel }) => {
    const [jsonText, setJsonText] = useState('');
    const textAreaRef = useRef<HTMLTextAreaElement>(null);

    useEffect(() => {
        // Auto-focus the textarea when the modal appears
        textAreaRef.current?.focus();
    }, []);

    const handleImportClick = () => {
        if (jsonText.trim()) {
            onImport(jsonText);
        }
    };

    return (
        <div className="fixed inset-0 bg-black/70 z-[100] flex items-center justify-center" onClick={onCancel} aria-modal="true" role="dialog">
            <div className="bg-gray-800 rounded-lg shadow-xl p-6 w-full max-w-lg" onClick={e => e.stopPropagation()}>
                <h3 className="text-xl font-bold text-white">Import Plan from Text</h3>
                <p className="text-gray-300 mt-2">Paste the JSON content of a workout plan below.</p>
                <textarea
                    ref={textAreaRef}
                    value={jsonText}
                    onChange={e => setJsonText(e.target.value)}
                    className="w-full h-48 mt-4 p-2 bg-gray-900 text-gray-300 rounded-md font-mono text-sm focus:outline-none focus:ring-2 ring-blue-500"
                    placeholder='{ "id": "...", "name": "...", "steps": [...] }'
                />
                <div className="mt-6 flex justify-end gap-4">
                    <button onClick={onCancel} className="px-4 py-2 rounded-md text-white bg-gray-600 hover:bg-gray-500 font-semibold">Cancel</button>
                    <button onClick={handleImportClick} className="px-4 py-2 rounded-md text-white bg-blue-600 hover:bg-blue-700 font-semibold">Import</button>
                </div>
            </div>
        </div>
    );
};

const PlanList: React.FC<{
  onSelectPlan: (plan: WorkoutPlan | string) => void;
  onCreateNew: () => void;
  onInitiateDelete: (planId: string) => void;
  onShowLog: () => void;
  onInspectExercise: (exerciseName: string) => void;
  onShowInfo: (plan: WorkoutPlan) => void;
  isPinned: boolean;
  onTogglePin: () => void;
  onOpenAiPlanner: () => void;
}> = ({ onSelectPlan, onCreateNew, onInitiateDelete, onShowLog, onInspectExercise, onShowInfo, isPinned, onTogglePin, onOpenAiPlanner }) => {
  const { plans, reorderPlans, startWorkout, importPlan, activeWorkout, recentlyImportedPlanId, isSyncing, forceSync, savePlan } = useWorkout();
  const { settings, updateSettings } = useSettings();
  const { user, authStatus, signIn, signOut } = useAuth();

  const [selectedPlanIds, setSelectedPlanIds] = useState<string[]>([]);
  // Split state for drag and drop to support two lists
  const dragSource = useRef<{ index: number, listType: 'pinned' | 'unpinned' } | null>(null);
  const [dragTarget, setDragTarget] = useState<{ index: number, listType: 'pinned' | 'unpinned' } | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [isImportTextVisible, setIsImportTextVisible] = useState(false);
  const [sharingPlan, setSharingPlan] = useState<WorkoutPlan | null>(null);
  const [refreshStatus, setRefreshStatus] = useState<'idle' | 'loading' | 'success' | 'partial' | 'error'>('idle');
  const [refreshFeedback, setRefreshFeedback] = useState<string | null>(null);
  const [isWarmupSettingsExpanded, setIsWarmupSettingsExpanded] = useState(false);
  const [isUserDropdownOpen, setIsUserDropdownOpen] = useState(false);
  const userDropdownRef = useRef<HTMLDivElement>(null);

  const planRefs = useRef<Record<string, HTMLDivElement | null>>({});
  const lastScrolledPlanId = useRef<string | null>(null);

  // Memoize sorted lists to ensure stability
  const pinnedPlans = useMemo(() => plans.filter(p => p.isPinned), [plans]);
  const unpinnedPlans = useMemo(() => plans.filter(p => !p.isPinned), [plans]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (userDropdownRef.current && !userDropdownRef.current.contains(event.target as Node)) {
        setIsUserDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Effect to scroll to a newly imported plan
  useEffect(() => {
    if (recentlyImportedPlanId && recentlyImportedPlanId !== lastScrolledPlanId.current) {
        // Use a timeout to allow the DOM to update and the modal to close
        setTimeout(() => {
            const element = planRefs.current[recentlyImportedPlanId];
            if (element) {
                element.scrollIntoView({ behavior: 'smooth', block: 'center' });
                lastScrolledPlanId.current = recentlyImportedPlanId;
            }
        }, 300);
    }
  }, [recentlyImportedPlanId]);


  const handleRefreshAll = async () => {
    if (refreshStatus === 'loading' || plans.length === 0) return;

    setRefreshStatus('loading');
    setRefreshFeedback('Checking server for missing exercises...');
    const allExerciseNames = plans.flatMap(plan => plan.steps)
                                  .filter(step => step.type === 'exercise')
                                  .map(step => step.name); // Already base name

    const result = await prefetchExercises(allExerciseNames);

    if (result.failedCount === 0) {
        setRefreshStatus('success');
        setRefreshFeedback('All exercises are up to date!');
    } else if (result.failedCount > 0 && result.successCount > 0) {
        setRefreshStatus('partial');
        setRefreshFeedback(`Failed to refresh: ${result.failedNames.join(', ')}`);
    } else {
        setRefreshStatus('error');
        setRefreshFeedback(`Failed to refresh all missing exercises: ${result.failedNames.join(', ')}`);
    }

    setTimeout(() => {
        setRefreshStatus('idle');
        setRefreshFeedback(null);
    }, 8000);
  };

  const getRefreshTooltip = () => {
    if (refreshFeedback) return refreshFeedback;
    switch (refreshStatus) {
        case 'loading': return "Refreshing info in background...";
        case 'success': return "All exercise info is up to date!";
        default: return "Sync all exercises with the database";
    }
  };

  const handleToggleSelection = (planId: string) => {
    setSelectedPlanIds(prev =>
      prev.includes(planId) ? prev.filter(id => id !== id) : [...prev, planId]
    );
  };

  const handleStartSelected = () => {
      startWorkout(selectedPlanIds);
      setSelectedPlanIds([]);
  };

  const handleImportClick = () => {
      fileInputRef.current?.click();
  };

  const handleShare = async (plan: WorkoutPlan) => {
    try {
        const planJson = JSON.stringify(plan);
        const encoder = new TextEncoder();
        const data = encoder.encode(planJson);
        const binaryString = Array.from(data, byte => String.fromCharCode(byte)).join('');
        const base64Data = btoa(binaryString);

        const url = new URL(window.location.href);
        url.hash = `import=${base64Data}`;
        url.search = '';
        const shareableLink = url.toString();

        const shareData = {
            title: `Workout Plan: ${plan.name}`,
            text: `Check out the "${plan.name}" workout plan!`,
            url: shareableLink,
        };

        if (navigator.share) {
            await navigator.share(shareData);
        } else {
            setSharingPlan(plan);
        }
    } catch (error) {
        if ((error as DOMException).name !== 'AbortError') {
            console.error("Share failed, falling back to modal:", error);
            setSharingPlan(plan);
        }
    }
  };

  const handleTogglePlanPin = (plan: WorkoutPlan) => {
      savePlan({ ...plan, isPinned: !plan.isPinned });
  };

  const handleFileChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = event.target.files;
    if (!files || files.length === 0) return;

    Array.from(files).forEach((file: File) => {
        const reader = new FileReader();
        reader.onload = (e) => {
            try {
                const text = e.target?.result as string;
                handleJsonImport(text, 'file');
            } catch (error) {
                console.error("Failed to read file:", error);
                alert(`Could not read the file: ${file.name}`);
            }
        };
        reader.readAsText(file);
    });

    if (fileInputRef.current) {
        fileInputRef.current.value = '';
    }
  };

  const handleJsonImport = (jsonText: string, source: string) => {
    try {
        const importedPlan = JSON.parse(jsonText);
        // Basic validation
        if (importedPlan && typeof importedPlan.name === 'string' && Array.isArray(importedPlan.steps)) {
            importPlan(importedPlan, source);
            setIsImportTextVisible(false); // Close modal on success
        } else {
            throw new Error("Invalid plan structure.");
        }
    } catch (error) {
        console.error("Failed to import plan:", error);
        alert("Could not import plan. The file may be corrupted or in the wrong format.");
    }
  };

  const onDragStart = (e: React.DragEvent, index: number, listType: 'pinned' | 'unpinned') => {
    dragSource.current = { index, listType };
    e.dataTransfer.effectAllowed = 'move';
  };

  const onDragOver = (e: React.DragEvent, index: number, listType: 'pinned' | 'unpinned') => {
    e.preventDefault();
    // Only allow dropping in the same list type
    if (!dragSource.current || dragSource.current.listType !== listType) return;

    if (!dragTarget || dragTarget.index !== index || dragTarget.listType !== listType) {
      setDragTarget({ index, listType });
    }
    e.dataTransfer.dropEffect = 'move';
  };

  const onDrop = (e: React.DragEvent, index: number, listType: 'pinned' | 'unpinned') => {
    e.preventDefault();
    if (!dragSource.current || dragSource.current.listType !== listType) return;

    if (dragSource.current.index === index) {
        setDragTarget(null);
        return;
    }

    // We are reordering within the same visual list (pinned or unpinned)
    const sourceList = listType === 'pinned' ? [...pinnedPlans] : [...unpinnedPlans];
    const otherList = listType === 'pinned' ? unpinnedPlans : pinnedPlans;

    const [movedItem] = sourceList.splice(dragSource.current.index, 1);
    sourceList.splice(index, 0, movedItem);

    // Reconstruct full list to save order
    // Order matters: if 'pinned' changed, put it first then 'unpinned'.
    const newFullList = listType === 'pinned' 
        ? [...sourceList, ...otherList] 
        : [...otherList, ...sourceList];

    reorderPlans(newFullList);

    dragSource.current = null;
    setDragTarget(null);
  };

  const onDragEnd = () => {
    dragSource.current = null;
    setDragTarget(null);
  };

  const onDragLeave = () => {
    setDragTarget(null);
  };

  return (
    <div>
      {sharingPlan && <ShareModal plan={sharingPlan} onClose={() => setSharingPlan(null)} />}
      <div className="flex justify-between items-center mb-4">
        {/* Left Side: Auth display (Guest only) */}
        <div>
           {authStatus !== 'authenticated' && (
            <div className="flex flex-col items-center">
              <p className="text-gray-400 text-xs mb-1">אורח</p>
              <button
                  onClick={signIn}
                  className="bg-white text-gray-700 text-sm py-1 px-3 rounded-full border border-gray-200 shadow-sm hover:shadow-md transition-shadow flex items-center gap-2"
                  aria-label="התחברות עם גוגל"
              >
                  <svg version="1.1" xmlns="http://www.w3.org/2000/svg" width="16px" height="16px" viewBox="0 0 48 48">
                    <path fill="#EA4335" d="M24 9.5c3.54 0 6.71 1.22 9.21 3.6l6.85-6.85C35.9 2.38 30.47 0 24 0 14.62 0 6.51 5.38 2.56 13.22l7.98 6.19C12.43 13.72 17.74 9.5 24 9.5z"></path>
                    <path fill="#4285F4" d="M46.98 24.55c0-1.57-.15-3.09-.38-4.55H24v9.02h12.94c-.58 2.96-2.26 5.48-4.78 7.18l7.73 6c4.51-4.18 7.09-10.36 7.09-17.65z"></path>
                    <path fill="#FBBC05" d="M10.53 28.59c-.48-1.45-.76-2.99-.76-4.59s.27-3.14.76-4.59l-7.98-6.19C.92 16.46 0 20.12 0 24c0 3.88.92 7.54 2.56 10.78l7.97-6.19z"></path>
                    <path fill="#34A853" d="M24 48c6.48 0 11.93-2.13 15.89-5.81l-7.73-6c-2.15 1.45-4.92 2.3-8.16 2.3-6.26 0-11.57-4.22-13.47-9.91l-7.98 6.19C6.51 42.62 14.62 48 24 48z"></path>
                    <path fill="none" d="M0 0h48v48H0z"></path>
                  </svg>
                  <span className="whitespace-nowrap">התחברות</span>
              </button>
            </div>
           )}
        </div>

        {/* Right Side: Action buttons & logged-in user display */}
        <div className="flex items-center gap-2">
            {isSyncing && (
                <div className="p-2" title="Syncing...">
                    <svg className="animate-spin h-5 w-5 text-gray-400" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                </div>
            )}
            {user && (
              <div className="relative" ref={userDropdownRef}>
                <button onClick={() => setIsUserDropdownOpen(!isUserDropdownOpen)} className="flex items-center">
                    <img
                        src={user.photoURL!}
                        alt="User profile"
                        className="w-10 h-10 rounded-full border-2 border-gray-600 hover:border-blue-500 transition-colors"
                    />
                </button>
                {isUserDropdownOpen && (
                    <div className="absolute left-0 mt-2 w-56 bg-gray-700 rounded-md shadow-lg py-1 z-10 animate-fadeIn">
                        <div className="px-4 py-2 text-sm text-gray-300 border-b border-gray-600">
                            <p className="font-semibold text-white">{user.displayName}</p>
                            <p className="truncate">{user.email}</p>
                        </div>
                        <button
                            onClick={forceSync}
                            className="flex items-center gap-3 w-full text-left px-4 py-2 text-sm text-gray-200 hover:bg-gray-600/70"
                        >
                            <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                              <path strokeLinecap="round" strokeLinejoin="round" d="M4 4v5h5M20 20v-5h-5" />
                              <path strokeLinecap="round" strokeLinejoin="round" d="M4 9a9 9 0 0114.13-5.23M20 15a9 9 0 01-14.13 5.23" />
                            </svg>
                            <span>Sync Data</span>
                        </button>
                        <button
                            onClick={signOut}
                            className="flex items-center gap-3 w-full text-left px-4 py-2 text-sm text-red-400 hover:bg-red-500/20"
                        >
                           <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                             <path strokeLinecap="round" strokeLinejoin="round" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
                           </svg>
                            <span>Sign Out</span>
                        </button>
                    </div>
                )}
              </div>
            )}
            <button
                onClick={handleRefreshAll}
                className={`p-2 rounded-full hover:bg-gray-500/30 disabled:opacity-50 disabled:cursor-not-allowed transition-colors`}
                title={getRefreshTooltip()}
                disabled={refreshStatus === 'loading' || !!activeWorkout}
            >
                {refreshStatus === 'loading' ? (
                    <svg className="animate-spin h-6 w-6 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                ) : (
                    <svg xmlns="http://www.w3.org/2000/svg" className={`h-6 w-6 ${
                        refreshStatus === 'success' ? 'text-green-400' :
                        refreshStatus === 'partial' ? 'text-yellow-400' :
                        refreshStatus === 'error' ? 'text-red-400' :
                        'text-gray-400'
                    }`} fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                      <path strokeLinecap="round" strokeLinejoin="round" d="M4 4v5h5M20 20v-5h-5" />
                      <path strokeLinecap="round" strokeLinejoin="round" d="M4 9a9 9 0 0114.13-5.23M20 15a9 9 0 01-14.13 5.23" />
                    </svg>
                )}
            </button>
            <button
                onClick={onShowLog}
                className="p-2 rounded-full hover:bg-gray-500/30 text-gray-400"
                title="View Workout Log"
            >
                <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" viewBox="0 0 20 20" fill="currentColor">
